func:
// array for output 
let outputArray = [];

// battery to target
const target = `marstek_m${msg.battery_index}`;

// Set | work mode
const workModeAction = {
    "action": "select.select_option",
    "target": {
        "entity_id": [`select.${target}_user_work_mode`]
    },
    "data": {
         "option": String(msg.work_mode)
    }
};
// Add to output array. Set null for no action.
outputArray.push(msg.work_mode ? { payload: workModeAction, topic:"user_work_mode"}: null);

// Set | rs485
const rs485Action = {
    "action": "select.select_option",
    "target": {
        "entity_id": [`select.${target}_rs485_control_mode`]
    },
    "data": {
         "option": String(msg.rs485)
    }
};
// Add to output array. Set null for no action.
outputArray.push(msg.rs485 ? { payload: rs485Action, topic: "rs485_control_mode" } : null);

// Store calls in msg to allow checking of loop results
msg.loop_result = { target, workModeAction, rs485Action };

// Return msg as third output
outputArray.push(msg);

// Outputs
return outputArray;

// loop through the number of batteries set by the user
msg.battery_index = 1; // base-1

// configurables
let workMode = null; // manual, anti-feed, ai, null = don't set or alter this setting
let rs485 = null;  // enable, disable, null = don't set or alter this setting

// mode select
switch (msg.marstek_master_battery_mode) {
    case "Manual control":
        workMode = "manual";
        rs485 = "disable";
        break;
    case "Marstek control":
        // the user should select a work mode via the Marstek App or via select.marstek_mX_user_work_mode
        rs485 = "disable";
        break;
    case "Full control":
        rs485 = "enable";
        break;
    default:
        node.status({fill:"red",shape:"ring",text:`Unhandled mode: ${msg.marstek_master_battery_mode}`});
        return null; // stop flow
}

// Continue
msg.work_mode = workMode;
msg.rs485 = rs485;
return msg;

// Step index down
msg.battery_index += 1;

// Continue
return msg;

// See: house_battery_control.yaml > input_select: > house_battery_control_pid_presets
const preset = RED.util.getMessageProperty(msg,"payload");
node.status({fill:"green",shape:"dot",text:`${preset}`});


// Default values
let Kp = 0; // Proportional gain
let Ki = 0; // Integral gain
let Kd = 0; // Differentiating gain
let Si = 0; // % Input smoothing (a Low pass moving average filter)
let So = 0; // % Output smoothing (a Low pass moving average filter)

switch (preset) {
    // For people who have unstable systems with every other preset
    case "Very safe":
        Kp = 0.1;
        Ki = 0.1;
        Si = 0; // without Kd, this is preferred to be zero.
        So = 10; // %
        break;
    // Good starting point for most
    case "Safe":
        Kp = 0.3;
        Ki = 0.3;
        Kd = 0.1;
        Si = 20; // %
        So = 0; // %
        break;
    // Gitcodebob's October 2025 settings for 3.2kWp PV and 5kW battery transformer power
    case "Regular":
        Kp = 0.3;
        Ki = 0.4;
        Kd = 0.8;
        Si = 50; // % This high amount of filtering allows the stronger Kd
        So = 10; // %
        break;
    default:
        // Don't change values
        return null;
}

// Prepare for three outputs
return [
    { "payload": Kp },
    { "payload": Ki },
    { "payload": Kd },
    { "payload": Si },
    { "payload": So }
];

// Logger
const logger = global.get("logger");

// INFLOW
let strategy = flow.get("house_battery_strategy");

// Configure msg.strategy object
RED.util.setMessageProperty(msg,"strategy.selected",strategy,true); // by user
RED.util.setMessageProperty(msg,"strategy.trace",[],true); // init trace: which flows have been executed

// stop on error
if(msg.batteries === undefined) {
    logger(this, "Battery configuration undefined", "error");
    return null;
}
if(strategy === undefined) {
    logger(this, "Battery strategy undefined", "error");
    return null;
}

// Default | select target flow based on the input_select `house_battery_strategy`
msg.target = `${strategy}`;

// EV stop trigger overrules selected strategies, except a manual Full stop.
const stopTrigger = RED.util.getMessageProperty(msg,"full_stop_trigger");
const isStopTriggerActive = stopTrigger == "on" || stopTrigger === true || stopTrigger === 1;
if(isStopTriggerActive && strategy !== "Full stop") {
    const stopTriggerStrategy = RED.util.getMessageProperty(msg,"ev_stop_trigger_strategy") || "Full stop";
    msg.target = stopTriggerStrategy;
    // Explain
    logger(this, `**${stopTriggerStrategy}** strategy selected, due to EV stop trigger: '${stopTrigger}'`);
}

// add execution marker
RED.util.setMessageProperty(msg,"strategy.execution_start",Date.now()); // when do we start executing the selected strategy

// OUTPUT
node.status({fill:"grey",shape:"dot",text:msg.target});
return msg;

// add execution marker
let execution_end = Date.now();
RED.util.setMessageProperty(msg, "strategy.execution_end", execution_end);

// retrieve execution markers
let execution_start = RED.util.getMessageProperty(msg,"strategy.execution_start");

// report execution time
if (execution_start !== undefined && execution_end !== undefined) {
    // exec time
    let execution_time = (execution_end - execution_start) / 1000; // seconds
    // report
    if (execution_time <= 0) node.status({ fill: "red", shape: "dot", text: `negative or zero timing` });
    if (execution_time > 0) node.status({ fill: "green", shape: "dot", text: `${execution_time} sec`});
    if (execution_time >= 0.7) node.status({ fill: "yellow", shape: "dot", text: `${execution_time} sec` });
    if (execution_time >= 1) node.status({ fill: "red", shape: "dot", text: `${execution_time} sec` });
    // store in flow context (so the rate limiter can evaluate at next pass)
    flow.set("strategy_execution_time", execution_time); // negative = error
} else {
    // report
    node.status({fill:"grey",shape:"dot",text:"timing error"});
    // store in flow context (so the rate limiter can evaluate at next pass)
    flow.set("strategy_execution_time", -1); // negative = error
}

return msg;

// loop through the number of batteries set by the user
msg.battery_index = 1; // base-1

// Init an array for battery status and value information
msg.batteries = [];

// Continue
return msg;

// Map to batteries array
msg.batteries.push({
    id: `M${msg.battery_index}`,
    power: parseInt(msg.battery_power,10),
    charging_max: parseInt(msg.max_charge_power,10),
    discharging_max: parseInt(msg.max_discharge_power,10),
    soc: parseInt(msg.battery_state_of_charge,10),
    soc_max: parseInt(msg.charging_cutoff_capacity,10),
    soc_min: parseInt(msg.discharging_cutoff_capacity,10),
    inverter: String(msg.inverter_state),
    energy: Number(msg.battery_remaining_capacity),
    energy_max: Number(msg.battery_total_energy),
    rs485: String(msg.rs485_control_mode)
    });

// Continue
return msg;

// Step index down
msg.battery_index += 1;

// Continue
return msg;

// Cycles battery priority as follows
// M=1 [1,2,3,4] | M=2 [2,3,4,1] | M=3 [3,4,1,2] | etc.
// With M the battery to prioritize

// msg.batteries (original order)
let currentArray = msg.batteries;

// Prioritize the Mth battery
const M = RED.util.getMessageProperty(msg,"prioritize_battery") || 1;

// Flag wether the order may be reversed when discharging (e.g. Self-consumption utilizes this)
const reverseDischargePriority = RED.util.getMessageProperty(msg,"battery_priority_cycle_interval") !== "Auto balance";
RED.util.setMessageProperty(msg, "advanced_settings.reverse_discharge_priority", reverseDischargePriority,true);

// 1st battery has prio? Skip and continue without change
if (M==1) return msg;

// N equals the number of items to take from the front to the back of the array, effectivly rotating battery priority
const N = M - 1; // base-0 version of M
node.status({fill:"blue",shape:"ring",text:`N = ${N}`});

// 1. Check if the array is valid and long enough
if (!Array.isArray(currentArray) || currentArray.length < N) {
    // Send an error or the original array back if the array is invalid/too short
    node.error(`Array is not valid or shorter than ${N} items.`, msg);
    return null;
}

// 2. Get the first N items (these will go to the back)
// slice(0, N) retrieves elements from the start (index 0) up to index N (exclusive).
let firstN = currentArray.slice(0, N);

// 3. Get the remaining items (these will stay at the front)
// slice(N) retrieves elements from index N to the end of the array.
let remaining = currentArray.slice(N);

// 4. Concatenate them: remaining items (front) + first N items (back)
let newArray = remaining.concat(firstN);

// 5. Place the new array back into msg.batteries
msg.batteries = newArray;

return msg;

// Current prioritized battery
let currentBattery = parseInt(RED.util.getMessageProperty(msg, "prioritize_battery"), 10) || 1;
const totalBatteries = parseInt(msg.battery_count, 10) || 1;

// Prioritize the next battery
currentBattery += 1;

// Loop back to the first battery if we exceed the total count
if (currentBattery > totalBatteries) {
    currentBattery = 1;
}

// Strictly enforce integer type on the output payload
msg.payload = parseInt(currentBattery, 10);

// Update node status visually in Node-RED
node.status({ fill: "green", shape: "dot", text: `Prioritize battery #${msg.payload}` });

return msg;

// Manual priority, never pass
if(msg.payload == "Never") {
    node.status({fill:"yellow",shape:"dot",text:"Auto cycle disabled"});
    return null;
}

const now = new Date();

// Auto balance: pass every 30 min trigger
if(msg.payload == "Auto balance") {
    node.status({ fill: "green", shape: "dot", text: `Auto balance` });
    return msg;
}

// Daily interval: pass at 02:00
if(msg.payload == "Daily") {
    if (now.getHours() === 2 && now.getMinutes() === 0) {
        node.status({ fill: "green", shape: "dot", text: `Daily at 02:00` });
        return msg;
    } else {
        node.status({ fill: "yellow", shape: "dot", text: `Halted, not 02:00` });
        return null;
    }
}

// Weekly interval
const dayOfWeek = now.getDay();

if (dayOfWeek === 0 && now.getHours() === 2 && now.getMinutes() === 0) {
    node.status({ fill: "green", shape: "dot", text: `Passed on Sunday` });
    return msg;
} else {
    node.status({ fill: "yellow", shape: "dot", text: `Halted, not Sunday 02:00` });
    return null;
}

// batteries | calculate total and max. power delivered by batteries
// 2026-10-23 (local guard): a battery whose RS485/Modbus entities are briefly 'unavailable'
// or 'unknown' gave NaN here. NaN reached HA as null ("expected float at 'value'") and made
// strategy comparisons silently false. Now, per battery and per value:
//   - valid number      -> used, and remembered as that battery's last good value
//   - not a number      -> the last good value is used for up to HOLD_MS (short reconnects)
//   - older / never seen -> the battery adds 0 to the totals that need that value (offline)
// msg.batteries itself is NOT changed, so Set Batteries and the strategies see the same
// per-battery data as before. Only the five totals below are guarded.
const HOLD_MS = 5 * 60 * 1000;
const FIELDS = ['power', 'charging_max', 'discharging_max', 'energy', 'energy_max', 'soc_min', 'soc_max'];

const now = Date.now();
const lastGood = context.get('lastGood') || {};
const held = [];     // "M2 energy (12 s)"
const missing = [];  // "M2 energy"

let batteries = msg.batteries || [];
let batteries_total_power = 0;
let batteries_max_charging_power = 0;
let batteries_max_discharging_power = 0;
let batteries_available_energy = 0;
let batteries_max_energy = 0;

batteries.forEach((battery, idx) => {
    const id = battery.id || `M${idx + 1}`;
    const store = lastGood[id] || (lastGood[id] = {});
    const v = {};
    FIELDS.forEach(f => {
        const n = Number(battery[f]);
        if (battery[f] !== null && battery[f] !== '' && Number.isFinite(n)) {
            v[f] = n;
            store[f] = { v: n, t: now };
        } else if (store[f] && now - store[f].t <= HOLD_MS) {
            v[f] = store[f].v;
            held.push(`${id} ${f} (${Math.round((now - store[f].t) / 1000)} s)`);
        } else {
            v[f] = undefined;
            missing.push(`${id} ${f}`);
        }
    });
    const ok = (...f) => f.every(k => v[k] !== undefined);

    if (ok('power')) batteries_total_power += v.power;
    if (ok('charging_max')) batteries_max_charging_power += v.charging_max;
    if (ok('discharging_max')) batteries_max_discharging_power += v.discharging_max;
    if (ok('energy', 'energy_max', 'soc_min'))
        batteries_available_energy += v.energy - v.energy_max * v.soc_min / 100;
    if (ok('energy_max', 'soc_max', 'soc_min'))
        batteries_max_energy += (v.energy_max * v.soc_max - v.energy_max * v.soc_min) / 100; // kWh
});
context.set('lastGood', lastGood);

// status + one warning per change of state (not every tick)
let text, fill;
if (missing.length) { fill = 'red'; text = `counted as 0: ${missing.join(', ')}`; }
else if (held.length) { fill = 'yellow'; text = `holding last value: ${held.join(', ')}`; }
else { fill = 'green'; text = `${batteries.length} batteries OK`; }
const stateKey = fill + '|' + missing.join(',') + '|' + held.map(h => h.replace(/ \(\d+ s\)$/, '')).join(',');
if (context.get('stateKey') !== stateKey) {
    if (fill !== 'green') node.warn(`Batteries (totals): ${text}`);
    context.set('stateKey', stateKey);
}
node.status({ fill, shape: fill === 'green' ? 'dot' : 'ring', text: text.length > 90 ? text.slice(0, 87) + '...' : text });

// OUTPUT
RED.util.setMessageProperty(msg, "batteries_total_power", batteries_total_power, true); // W
RED.util.setMessageProperty(msg, "batteries_max_charge_power", batteries_max_charging_power,true); // W
RED.util.setMessageProperty(msg, "batteries_max_discharge_power", batteries_max_discharging_power,true); // W
RED.util.setMessageProperty(msg, "batteries_available_energy",batteries_available_energy,true); // kWh usable
RED.util.setMessageProperty(msg, "batteries_max_energy", batteries_max_energy, true); // kWh usable
return msg;

// cleanup 
delete msg.battery_index;

delete msg.battery_power;
delete msg.max_charge_power;
delete msg.max_discharge_power;
delete msg.battery_state_of_charge;
delete msg.charging_cutoff_capacity;
delete msg.discharging_cutoff_capacity;
delete msg.inverter_state;
delete msg.battery_remaining_capacity;
delete msg.battery_total_energy;
delete msg.rs485_control_mode;

return msg;

// Switch between low and high rate limiting to decrease load and power consumption
// --
// The flow should always be rate limited by atleast the total execution time of strategies
// The flow should not lock up indefinitly when grid_power is constant.
// In the latter case, a more relaxed rate limit can help reduce system load.
// Devs: don't set msg.rate directly. Use nodes, so novice users can easily read the flow.

// Thresholds for change in power, before switching to high rate limit
const THRESHOLD_POWER = 20; // Watt change
const THRESHOLD_PERCENT = 2; // Percentage
RED.util.setMessageProperty(msg, "p1_rate_limit.threshold_power", THRESHOLD_POWER,true);
RED.util.setMessageProperty(msg, "p1_rate_limit.threshold_percent", THRESHOLD_PERCENT, true);

// Threshold strategy execution times
const THRESHOLD_EXECUTION_TIME = 1.0; // strategy execution time in seconds
RED.util.setMessageProperty(msg, "p1_rate_limit.threshold_execution_time", THRESHOLD_EXECUTION_TIME, true);
// Time spent on calculating a solution using the users strategies
const strategyTime = flow.get("strategy_execution_time") || 0;
// Time spent on sending the solutions via Modbus to the batteries
const writeTime = flow.get("write_execution_time") || 0;
RED.util.setMessageProperty(msg, "p1_rate_limit.previous_write_time", writeTime, true);

// We take the one that took the longest (e.g. the effective bottleneck)
const previousExecutionTime = (strategyTime < 0 || writeTime < 0)
    ? -1
    : Math.max(strategyTime, writeTime);
RED.util.setMessageProperty(msg, "p1_rate_limit.previous_execution_time", previousExecutionTime, true);

// Default rate limiting
RED.util.setMessageProperty(msg,"p1_rate_limit.save_power",true);

// Evaluate execution time
RED.util.setMessageProperty(msg,"p1_rate_limit.high_load_detected",false);
if(previousExecutionTime < 0 || previousExecutionTime > THRESHOLD_EXECUTION_TIME){
    // HIGH LOAD detected, let system the system cool down for the duration of the save power limiter
    RED.util.setMessageProperty(msg,"p1_rate_limit.high_load_detected",true);
    node.status({fill:"yellow",shape:"dot",text:"High load, cooling down"});
    return msg;
}

// Get the previous value from this node's context
// If it doesn't exist yet, initialize it as null
let previousP1Value = context.get('previousValue') || null;
let currentP1Value = Number(msg.grid_power);

// Save the current value for the next time the node is triggered
context.set('previousValue', currentP1Value);

// Check if we have a valid history to compare with
if (previousP1Value !== null) {
    let powerChange = Math.abs(currentP1Value - previousP1Value);
    let percentageChange = previousP1Value !== 0 ? Math.abs((powerChange / previousP1Value) * 100):0;

    // Condition: Absolute difference > N Watt AND percentage change > M %
    if (powerChange > THRESHOLD_POWER && percentageChange > THRESHOLD_PERCENT) {
        // Enable faster refresh rate
        RED.util.setMessageProperty(msg,"p1_rate_limit.save_power",false);
        node.status({fill:"green",shape:"dot",text:"Nominal"});
    } else {
        node.status({fill:"green",shape:"dot",text:"Stable"});
    }
}

return msg;

// Logger
const logger = global.get("logger");

// Passed or blocked
const hasPassed = msg.payload; // 0 = blocked, 1 = passed

// 1. Get evaluations (Total attempts)
let evaluations = (context.get("p1_rate_limit_evaluations") || 0) + 1;
context.set("p1_rate_limit_evaluations", evaluations);

// 2. Increment and get passes (Filtered/successful events)
let passes = (context.get("p1_rate_limit_passes") || 0) + hasPassed;
context.set("p1_rate_limit_passes", passes);

// 3a. Calculate percentage (Rate of passing vs total evaluations)
let percentage = evaluations > 0 ? (passes / evaluations) * 100 : 0;
// 3b. Display the percentage rate of not-passing as a measure of efficiency gained
percentage = 100 - percentage;

// 4. Update Node Status
node.status({
    fill: "blue",
    shape: "dot",
    text: `Saved: ${percentage.toFixed(2)}% (${evaluations-passes}/${evaluations})`
});

// 5. Explain
// On block
if(hasPassed === 0) {
    if(msg.p1_rate_limit.save_power === true) {
        if(msg.p1_rate_limit.high_load_detected === false){
            // This is good
            logger(this, `<font color="#009ac7">Power saved</font> by P1 Rate Limiter, execution stopped.`); 
        } else {
            // This is not so good. The system is overloaded and needs to 'cool'
            logger(this, `<font color="orange">Blocked</font> by P1 Rate Limiter. High load detected. Cool down active. Execution time: ${Number(msg.p1_rate_limit.previous_execution_time).toFixed(3)} sec.`);     
        }
    } else {
        // This is not so good. P1 updates are coming in fast.
        logger(this, `<font color="orange">Blocked</font> by P1 Rate Limiter. ${Number(1000/msg.rate).toFixed(2)} messages per second exceeded.`); 
    }

    // Send message onward to debug dashboard
    return msg;
}
// No output on pass
return null;

// Block when undefined (don't update UI)
if(msg.ui_value_current === undefined) return null;

// Prefer an explicit display name, then active sub-strategy, otherwise show the executed flow.
const firstTraceEntry = msg.strategy?.trace?.[0];
const secondTraceEntry = msg.strategy?.trace?.[1];
const displayedTraceEntry = secondTraceEntry || firstTraceEntry;
msg.ui_value_new = msg.strategy?.display || displayedTraceEntry?.flow || msg.target || msg.strategy?.selected || ""; // don't use unknown or unavailable as these are reserved HA keywords

// Improve human readability when no explicit display name was provided.
if(!msg.strategy?.display && msg.ui_value_new == "Self-consumption" && displayedTraceEntry?.flow_settings?.charge_disabled === true && displayedTraceEntry?.flow_settings?.discharge_disabled === true){
    msg.ui_value_new = "Standby / peak shave";
}
if(!msg.strategy?.display && msg.ui_value_new == "Self-consumption" && displayedTraceEntry?.flow_settings?.discharge_disabled === true){
    msg.ui_value_new = "Self-consumption (charge only)";
}
if(!msg.strategy?.display && msg.ui_value_new == "Self-consumption" && displayedTraceEntry?.flow_settings?.charge_disabled === true){
    msg.ui_value_new = "Self-consumption (no charging)";
}
if(msg.strategy?.is_peak_shaving === true){
    msg.ui_value_new = "Peak shaving";
}

// Node status for devs
node.status({fill:"grey",shape:"dot",text:`new: ${msg.ui_value_new}`});

// Block when equal (don't update UI)
if(msg.ui_value_current === msg.ui_value_new) return null;

// Pass otherwise
return msg;

/**
 * Custom Logger Function
 * * Provides centralized logging, node-status updates, and message tracing.
 * Specifically designed for Home Battery Control logic within Node-RED.
 * 
 * Debug dashboard updating:
 * A msg needs to reach 'Strategy Evaluation' or be passed to the "Show on debug board" trigger node.
 * Errors are automatically passed to the "Show on debug board" trigger node.
 * 
 * * @param {object} callingNode - The context of the calling node (pass 'this').
 * @param {string} text - The log message/explanation.
 * @param {string} level - Log level: 'log', 'warn', 'error', or 'info' (default: 'info').
 * 
 * Note: anything above 'info' will also write to the Node-RED log files 
 * 
 * * @usage: 
 * const log = global.get("logger");
 * log(this, "Charging cycle started");
 */
const customLogger = (callingNode, text, level = 'info') => {

    // Log only when debug_mode is ON
    const debug_mode = global.get("debug_mode") || false;
    if(debug_mode == false) return null;

    // Max log elements to keep
    const MAX_ELEMENTS = 100;

    // Create the YYYY-MM-DD HH:MM:SS.mmm format
    const now = new Date();
    const timestamp = now.getHours().toString().padStart(2, '0') + ":" +
                now.getMinutes().toString().padStart(2, '0') + ":" +
                now.getSeconds().toString().padStart(2, '0') + "." +
                now.getMilliseconds().toString().padStart(3, '0');

    const formattedTimeLevel = `${timestamp} [${level.toLowerCase()}]`;

    // Get the name of the node or fallback to the ID
    const nodeName = callingNode.__node__ ? callingNode.__node__.name || callingNode.__node__.id : undefined;
    // Get the name of the Flow/Tab
    const flowName = callingNode.env.get("NR_FLOW_NAME") || "Unknown flow";
    // Explain to the Home Battery Control user what is going on
    const formattedExplenation = `[${flowName} >> ${nodeName}]: ${text}`;

    // Level icons
    let icon = "⚪";
    switch (level) {
        case "info":
            icon = "ℹ️";
            break;
        case "log":
            icon = "🔧";
            break;
        case "warn":
            icon = "⚠️";      
            break;
        case "error":
            icon = "❌";
            break;
    }

    // Enrich msg with log info
    const msg = callingNode.msg;
    (msg.log = msg.log || []).push({ timestamp: timestamp, level:level, flow:flowName, node:nodeName, payload: text, icon: icon});

    if (msg.log.length > MAX_ELEMENTS) {
        // Slice keeps the last X elements
        msg.log = msg.log.slice(-MAX_ELEMENTS);
    }

    // Log to the Node-RED system log
    switch (level) {
        case "log":
            node.log(`${formattedExplenation}`);
            break;
        case "warn":
            node.warn(`${formattedExplenation}`);       
            break;
        case "error":
            node.error(`${formattedExplenation}`, callingNode.msg);
            break;
        default:
            // don't log to logfiles by default
    }

};

global.set('logger', customLogger);
global.set('unhandledException', "");
return msg;

// enable or disable Insights Mode
if(msg.debug_mode == "on"){
    // ENABLED - explain to user
    const log = global.get("logger");
    log(this, "P1 Rate limiter is *disabled* during *debug mode*");

    // Set global (setting this via current state node has proven irriliable)
    global.set("debug_mode", true);
} else {
    // DISABLED - set global
    global.set("debug_mode", false);
}

// Clean up - only use the global
delete msg.debug_mode;

return msg;

/**
 * Handles exceptions by extracting node details and routing them to a global logger.
 * This is designed to be called from within a Node-RED Function node or sub-flow.
 *
 * @param {Object} callingNode - The Node-RED 'this' context or msg object containing node metadata.
 * @param {Object} [callingNode.msg] - The message object associated with the error.
 * @param {Object} [callingNode.msg.error] - Error details provided by a Node-RED error catch.
 * @param {string} [callingNode.msg.error.message] - The specific error message.
 * @param {Object} [callingNode.msg.error.source] - The node that triggered the error.
 * * @example
 * // Usage in a Function Node:
 * const unhandledException = global.get('unhandledException');
 * unhandledException(this);
 */
const unhandledException = (callingNode) => {
    // 1. Get the custom logger from global context
    const log = global.get("logger");

    // 2. Extract error details from the msg object
    const errorData = callingNode.msg?.error || {};
    const errorMessage = errorData.message || "Unknown error occurred";
    const sourceName = errorData.source ? (errorData.source.name || errorData.source.id) : "Unknown Node";
    const sourceType = errorData.source ? errorData.source.type : "unknown-type";

    // 3. Construct a user-friendly message for the logger
    const friendlyMessage = `**Unhandled exception** (${sourceType} node) ${errorMessage}`;
    callingNode.__node__ ??= {};
    callingNode.__node__.name = sourceName;

    // 4. Call the logger with level 'error'
    // Note: the logger uses 'callingNode', we pass on whatever we have.
    log(callingNode, friendlyMessage, 'error');

};

global.set('unhandledException', unhandledException);

return msg;

// Log unhandled exception
const handle = global.get('unhandledException');
if(handle) handle(this);

// Check origin of msg execution
if (msg._linkSource) {
    return msg; // Origin: some other flow
} else {
    return null; // Origin: this flow. Stop to prevent 'Missing return' warning
}

const log = global.get("logger");

// prepare grid power message
let state = "measure";
let ending = "";
if(msg.grid_power>0) {state = "import"; ending = "from grid";}
if(msg.grid_power<0) {state = "export"; ending = "to grid";}
const displayPower = Math.abs(Math.round(msg.grid_power));

// explain
log(this, `You currently ${state} ${displayPower} W ${ending}`);

return msg;

// 2026-10-13: read every Home Assistant value this tick needs in ONE node, straight from the
// HA states that node-red-contrib-home-assistant-websocket keeps in memory (global context,
// server option 'Expose to global context'). Replaces ~43 'current state' nodes in series:
// 10 per battery x battery count + 13 settings. Every one of those hops put the message back
// in Node-RED's queue; on a busy Node-RED that alone could take seconds.
//
// Sets EXACTLY the same msg / flow properties, with the same type conversions, as the old
// nodes did, and builds msg.batteries exactly like 'Mapping' did.
//
// Output 1 -> fast path (Batteries (totals), then straight to Update battery order and
//             Strategy selection via the two 'fast path?' switches).
// Output 2 -> FALLBACK: the original chain of current-state nodes, unchanged. Used when the
//             global states are not available (option off, HA not connected yet) or an
//             entity is missing - the old nodes then raise the same error as before.
const ha = global.get('homeassistant');
let states = null;
if (ha && typeof ha === 'object') {
    // keyed by the camel-cased server name; take a connected server that exposes its states
    const servers = Object.values(ha).filter(s => s && s.states && typeof s.states === 'object');
    const srv = servers.find(s => s.isConnected !== false) || servers[0];
    if (srv) states = srv.states;
}
const fallback = (why) => {
    const n = (context.get('fallbacks') || 0) + 1;
    context.set('fallbacks', n);
    node.status({ fill: 'yellow', shape: 'ring', text: `fallback to old reads (${why}) x${n}` });
    return [null, msg];
};
if (!states || Object.keys(states).length === 0) return fallback('no global HA states');

const missing = [];
const ent = (id) => {
    const e = states[id];
    if (!e) missing.push(id);
    return e;
};
// type conversions as the old outputProperties did them
const num = (id) => { const e = ent(id); return e ? Number(e.state) : undefined; };
const str = (id) => { const e = ent(id); return e ? String(e.state) : undefined; };
const raw = (id) => { const e = ent(id); return e ? e.state : undefined; };

// --- batteries (was: Your battery count, Loop start, 10 reads, Mapping, Loop step/until, Loop end)
const batteryCount = num('input_number.house_battery_count');
const batteries = [];
let i = 1;
do {   // the old loop ran the first battery before testing 'battery_index <= battery_count'
    const p = `marstek_m${i}_`;
    const b = {
        rs485_control_mode:          raw(`select.${p}rs485_control_mode`),
        battery_power:               num(`sensor.${p}battery_power`),
        max_charge_power:            num(`number.${p}max_charge_power`),
        max_discharge_power:         num(`number.${p}max_discharge_power`),
        battery_state_of_charge:     num(`sensor.${p}battery_state_of_charge`),
        discharging_cutoff_capacity: str(`input_number.${p}discharging_cutoff_capacity`),
        charging_cutoff_capacity:    str(`input_number.${p}charging_cutoff_capacity`),
        inverter_state:              raw(`sensor.${p}inverter_state`),
        battery_remaining_capacity:  num(`sensor.${p}battery_remaining_capacity`),
        battery_total_energy:        str(`sensor.${p}battery_total_energy`),
    };
    // 'Mapping', verbatim
    batteries.push({
        id: `M${i}`,
        power: parseInt(b.battery_power, 10),
        charging_max: parseInt(b.max_charge_power, 10),
        discharging_max: parseInt(b.max_discharge_power, 10),
        soc: parseInt(b.battery_state_of_charge, 10),
        soc_max: parseInt(b.charging_cutoff_capacity, 10),
        soc_min: parseInt(b.discharging_cutoff_capacity, 10),
        inverter: String(b.inverter_state),
        energy: Number(b.battery_remaining_capacity),
        energy_max: Number(b.battery_total_energy),
        rs485: String(b.rs485_control_mode)
    });
    i += 1;
} while (i <= batteryCount && i <= 20);   // 20 = guard against a runaway count

// --- settings (was: Prioritize battery M ... EV Stop Trigger Strategy)
const prioritize   = num('input_number.house_battery_control_prioritize_battery');
const cycle        = str('input_select.house_battery_control_priority_change_interval');
const hasImportE   = ent('input_boolean.house_battery_control_has_power_limit_import');
const hasExportE   = ent('input_boolean.house_battery_control_has_power_limit_export');
const importLimit  = num('input_number.house_battery_control_power_limit_import');
const exportLimit  = num('input_number.house_battery_control_power_limit_export');
const strategy     = str('input_select.house_battery_strategy');
const fullStop     = str('sensor.ev_is_charging');
const evStratE     = ent('input_select.house_battery_strategy_ev_stop_trigger_strategy');

if (missing.length) return fallback(`not in cache: ${missing[0]}${missing.length > 1 ? ' +' + (missing.length - 1) : ''}`);

msg.battery_count = batteryCount;
msg.batteries = batteries;
msg.prioritize_battery = prioritize;
msg.battery_priority_cycle_interval = cycle;
msg.grid_power_has_limit_import = hasImportE.state === 'on';
msg.grid_power_has_limit_export = hasExportE.state === 'on';
msg.grid_power_limit_import = importLimit;
msg.grid_power_limit_export = exportLimit;
flow.set('house_battery_strategy', strategy);
msg.full_stop_trigger = fullStop;
msg.ev_stop_trigger_strategy = String(evStratE.state);
// the last old node left these behind; keep them identical for anything downstream
msg.payload = String(evStratE.state);
msg.data = { ...evStratE };
msg._ha_fast_read = true;

node.status({ fill: 'green', shape: 'dot', text: `fast read: ${batteries.length} batteries @ ${new Date().toLocaleTimeString('nl-NL', { timeZone: 'Europe/Amsterdam' })}` });
return [msg, null];

// Proves the HBC control loop is running: fed from every tick (junction before
// 'Read HA states (fast)'). Publishes hbc/heartbeat (retained ISO time) at most once a
// minute -> sensor.hbc_last_run (packages/nodered_heartbeat.yaml). If it goes stale, HA
// hands the batteries back to their own firmware (anti-feed, RS485 off).
const EVERY_MS = 60 * 1000;
const now = Date.now();
if (now - (flow.get('hbc_hb_last') || 0) < EVERY_MS) return null;
flow.set('hbc_hb_last', now);
node.status({ fill: 'green', shape: 'dot', text: 'heartbeat ' + new Date(now).toLocaleTimeString('nl-BE', { timeZone: 'Europe/Brussels', hour: '2-digit', minute: '2-digit' }) });
return { payload: { topic: 'hbc/heartbeat', payload: new Date(now).toISOString(), retain: true, qos: 1 } };

// loop through the number of batteries set by the user
msg.battery_index = msg.battery_count;

// Debug
RED.util.setMessageProperty(msg, "debug", `## Cohort ${Date.now()} ##`);

// Continue
return msg;

// Logger
const log = global.get("logger");

// enums
// Debug board: the per-battery messages below are what reaches 'Show on debug board' (via
// Collect completions -> Write latency -> Pending solutions?), so they carry the cycle's trace
// and explanations. Without this the board shows an empty trace and 'No logs available'
// (same in upstream 4.15.1).
const debugInfo = () => ({ strategy: msg.strategy, log: Array.isArray(msg.log) ? msg.log.slice() : msg.log });

const CMODE = {
    STOP: "stop", // Marstek batteries disconnect a relay when this is set or Power is 0W
    CHARGE: "charge",
    DISCHARGE: "discharge"
}

// v4.15.1 merge (Tommelshof, 2026-10-22)
// From upstream 4.15.1: writes are awaited, one cycle at a time ('Write limiter'), and a value
// only counts as sent after the write succeeded ('Collect completions').
// Kept from the local version: the mode is NOT written every cycle, and only the power register
// in use is written (none in 'stop'). Instead of upstream's "always write the mode":
//   - mode  is written when it differs from the last SUCCESSFUL write, when HA's read-back of the
//           battery (select state = polled register 42010) disagrees and the last write is older
//           than READBACK_GRACE_MS, or every MODE_REFRESH_MS as a keep-alive;
//   - power is written when it differs from the last successful write, or when the read-back
//           (number state) disagrees and the last write is older than READBACK_GRACE_MS;
//   - power is written BEFORE the mode ('Next write' runs the queue in order), so a mode change
//     never starts on a stale value in the power register.
const MODE_REFRESH_MS = 60000;
const READBACK_GRACE_MS = 20000;   // longer than the modbus scan_interval (15 s default) of the read-back registers

// Loop steps on right away (output 3). Writes run per battery in parallel,
// because each battery has its own modbus hub. The collector waits for them.

let solution = msg.solutions[msg.battery_index-1]; // Base-0, thus -1
if (solution === undefined) {
    log(this,`Can't find solution for index ${msg.battery_index - 1}, skipping battery...`,"error");
    // Report done anyway, or the collector waits forever and holds the lock.
    return [null, {
        topic: "skipped",
        battery_count: msg.battery_count,
        setbatteries: msg.setbatteries,
        ...debugInfo(),
        skip_reason: "no solution"
    }, msg];
}

let target = `marstek_${solution.id.toLowerCase()}`;

// Safety | Id exists
let battery = msg.batteries.find(battery => battery.id === solution.id);
if (battery === undefined) {
    log(this,`Can't set battery ${solution.id}, skipping...`,"error");
    return [null, {
        topic: solution.id,
        battery_count: msg.battery_count,
        setbatteries: msg.setbatteries,
        ...debugInfo(),
        skip_reason: "unknown battery id"
    }, msg];
}

// Safety | Power limit
solution.power = Math.min(solution.power, solution.mode == CMODE.CHARGE ? battery.charging_max: battery.discharging_max);

const now = Date.now();

// HA read-back from the states the HA server node exposes in global context
// (undefined when that option is off or the entity is missing -> read-back is simply skipped)
const haState = (id) => {
    const ha = global.get('homeassistant');
    if (!ha || typeof ha !== 'object') return undefined;
    for (const srv of Object.values(ha)) {
        const e = srv && srv.states && srv.states[id];
        if (e) return e.state;
    }
    return undefined;
};
const usable = (v) => v !== undefined && v !== null && v !== '' && v !== 'unknown' && v !== 'unavailable';
const lastOf = (key) => { const v = flow.get(key); return (v && typeof v === 'object') ? v : null; };

// Set | Mode
const serviceCallMode = {
    "action": "select.select_option",
    "target": {
        "entity_id": [`select.${target}_forcible_charge_discharge`]
    },
    "data": {
         "option": String(solution.mode) // forced charge mode (stop, charge, discharge)
    }
};
const modeKey = `last_mode_${solution.id}`;          // {mode, ts}, set in 'Collect completions' on success
const lastMode = lastOf(modeKey);
const modeReadback = haState(`select.${target}_forcible_charge_discharge`);
let modeReason = null;
if (!lastMode || lastMode.mode !== solution.mode) {
    modeReason = "changed";
} else if (usable(modeReadback) && modeReadback !== solution.mode && now - lastMode.ts > READBACK_GRACE_MS) {
    modeReason = `read-back '${modeReadback}'`;
} else if (now - lastMode.ts >= MODE_REFRESH_MS) {
    modeReason = "keep-alive";
}

// Set | Power (only the register in use; nothing in 'stop')
let serviceCallPower = null;
let powerReason = null;
let powerSignature = null;
const powerKey = `last_power_${solution.id}`;        // {sig, ts}, set in 'Collect completions' on success
if (solution.mode !== CMODE.STOP) {
    const powerEntity = solution.mode == CMODE.DISCHARGE
        ? `number.${target}_forcible_discharge_power`
        : `number.${target}_forcible_charge_power`;
    serviceCallPower = {
        "action": "number.set_value",
        "target": {
            "entity_id": [powerEntity]
        },
        "data": {
            "value": Number(solution.power)
        }
    };
    powerSignature = JSON.stringify(serviceCallPower);
    const lastPower = lastOf(powerKey);
    const powerReadback = haState(powerEntity);
    if (!lastPower || lastPower.sig !== powerSignature) {
        powerReason = "changed";
    } else if (usable(powerReadback) && Number.isFinite(Number(powerReadback))
               && Math.abs(Number(powerReadback) - Number(solution.power)) > 1
               && now - lastPower.ts > READBACK_GRACE_MS) {
        powerReason = `read-back ${Number(powerReadback)} W`;
    }
}

// Write queue for this battery: power first, then mode
const writes = [];
if (powerReason) writes.push(serviceCallPower);
if (modeReason) writes.push(serviceCallMode);

// A message per battery, just for the awaited route. The loop continues using the regular full msg
const batteryMsg = {
    topic: solution.id,
    battery_id: solution.id,
    battery_count: msg.battery_count,
    setbatteries: msg.setbatteries,
    ...debugInfo(),
    write_queue: writes,
    mode_written: modeReason ? { key: modeKey, mode: solution.mode } : null,
    power_written: powerReason ? { key: powerKey, sig: powerSignature } : null
};

// Store service calls in msg to allow checking of loop results
msg.loop_result = { target, serviceCallMode, serviceCallPower, mode_reason: modeReason, power_reason: powerReason };

// Explain
const what = writes.length === 0 ? " (unchanged, nothing written)"
    : ` (write: ${[powerReason && `power ${powerReason}`, modeReason && `mode ${modeReason}`].filter(Boolean).join(", ")})`;
log(this,`${target} ${String(solution.mode)} @ ${Number(solution.power)} Watt${what}`);
batteryMsg.log = Array.isArray(msg.log) ? msg.log.slice() : msg.log;   // include the line just logged

// Nothing to write: report done straight to the collector (output 2)
if (writes.length === 0) return [null, batteryMsg, msg];
return [batteryMsg, null, msg];

// The loop only does bookkeeping now. Whether a write succeeded is tracked in
// 'Collect completions', which knows the outcome.

// Step index down
msg.battery_index -= 1;

// Continue
return msg;

// Allow one write cycle at a time. Only possible because 'Write done' gives
// a real completion signal; an unwired call output gives none.

const STALE_MS = 30000; // failsafe: never hold the lock longer than this, in milliseconds

const inflight = flow.get("write_inflight") || null;
const now = Date.now();

if (inflight !== null) {
    const age = now - inflight.t0;

    if (age < STALE_MS) {
        // Coalesce instead of drop: keep the newest setpoints in a slot of 1.
        // Dropping the latest setpoint is wrong for a control loop.
        flow.set("write_pending", msg);
        const total = (flow.get("write_coalesced") || 0) + 1;
        flow.set("write_coalesced", total);
        node.status({fill:"yellow",shape:"ring",text:`coalesced #${total} (in flight ${age} ms)`});
        return [null, { payload: { coalesced: true, inflight_age_ms: age, total } }];
    }

    // Previous cycle never finished. Without this the control stops for good.
    node.warn(`Write lock held for ${age} ms and was force released`);
    flow.set("write_acc", null);
}

flow.set("write_inflight", { t0: now });
flow.set("write_pending", null);
flow.set("write_acc", null);
node.status({fill:"blue",shape:"dot",text:"writing..."});
return [msg, null];

// Is there a coalesced setpoint waiting for dispatch? Coalesce means: slot of 1, newest wins, not a queue.
const pending = flow.get("write_pending") || null;
if (pending !== null) {
    flow.set("write_pending", null);
    return [msg, pending];
}

// Else done
return [msg, null];

// Cycle finished. HA's websocket call_service uses blocking=True, so the
// modbus.write_register is included in this time.

const inflight = flow.get("write_inflight") || null;
const latency = inflight ? Date.now() - inflight.t0 : null;

flow.set("write_inflight", null);

// The measurement the rate limiter needs. It only had
// strategy_execution_time, which is compute time, not write time.
if (latency !== null) flow.set("write_execution_time", latency / 1000);

let colour = "green";
if (latency !== null && latency >= 1000) colour = "yellow";
if (latency !== null && latency >= 3000) colour = "red";
node.status({ fill: colour, shape: "dot", text: `write ${latency} ms` });

// Wall clock of the cycle, not the sum of the writes: batteries run parallel.
msg.write_latency_ms = latency;

return msg;

// Report a failed battery anyway, or the collector waits for the stale
// failsafe and control stands still for 30 seconds.

const log = global.get("logger");
const reason = (msg.error && msg.error.message) ? msg.error.message : "unknown";
log(this, `Modbus write failed for ${msg.battery_id}: ${reason}`, "error");

node.status({fill:"red",shape:"ring",text:`write error: ${msg.battery_id}`});
return msg;

// Every battery reports here: done, skipped or failed. The cycle is complete
// once all of them are in, which is what lets them run in parallel.

// Mark what was written as sent, but only on success (a failed write is retried next cycle).
// Format {sig|mode, ts}: 'Set Batteries' also uses ts for its read-back grace period.
if (!msg.error) {
    const t = Date.now();
    if (msg.power_written && msg.power_written.key) flow.set(msg.power_written.key, { sig: msg.power_written.sig, ts: t });
    if (msg.mode_written && msg.mode_written.key) flow.set(msg.mode_written.key, { mode: msg.mode_written.mode, ts: t });
}

const cycle = flow.get("write_inflight") || null;
if (cycle === null) {
    // Late arrival from a cycle the stale failsafe already cleared.
    node.status({fill:"grey",shape:"ring",text:"late completion, ignored"});
    return null;
}

let acc = flow.get("write_acc") || null;
if (acc === null || acc.id !== cycle.t0) {
    acc = { id: cycle.t0, done: 0, failed: 0 };
}
acc.done += 1;
if (msg.error) acc.failed += 1;
flow.set("write_acc", acc);

const expected = Number(msg.battery_count) || 0;

if (acc.done < expected) {
    node.status({fill:"blue",shape:"ring",text:`${acc.done}/${expected} done`});
    return null;
}

// All batteries reported
flow.set("write_acc", null);
msg.batteries_done = acc.done;
msg.batteries_failed = acc.failed;
node.status({fill: acc.failed ? "yellow" : "green", shape:"dot", text:`${acc.done}/${expected} done, ${acc.failed} failed`});
// Debug board (2026-10-22): this msg goes on to Write latency -> Pending solutions? ->
// 'Show on debug board'. That fire-event node takes msg.payload.data as an OVERRIDE of its
// trace/log data, and msg.payload still holds the last HA call (e.g. {data: {value: 1733}}),
// so HA got {value: 1733} instead of the trace. Nothing downstream needs these two.
delete msg.payload;
delete msg.write_queue;
return msg;

// Runs this battery's write queue one awaited call at a time (power first, then mode).
// 'Write (awaited)' sends its output back here, so the next call only starts after the
// previous one completed. Queue empty -> this battery is done (output 2, collector).
// A failed call never comes back here: 'write errors' catches it and reports to the collector.
const q = Array.isArray(msg.write_queue) ? msg.write_queue : [];
if (q.length === 0) {
    node.status({fill:"green",shape:"dot",text:`${msg.battery_id}: done`});
    return [null, msg];
}
msg.payload = q.shift();
msg.write_queue = q;
node.status({fill:"blue",shape:"dot",text:`${msg.battery_id}: ${msg.payload.action}`});
return [msg, null];

// Charge Deadline v2 - place the energy the target needs inside the user's window.
//
// v2 adds, on top of v1:
//   * price-weighted pacing under Cheapest hours: each cheap quarter gets a weight
//     w = 1 + (ratio - 1) * (pHi - price) / (pHi - pLo), with pLo/pHi the price range of ALL
//     of today's cheap quarters (fixed all day, so re-planning every tick is stable). The
//     remaining energy is shared in proportion to w x minutes, so the total still lands on
//     the target by the deadline. ratio 1 = flat = v1.
//   * import-limit-aware planning: every quarter is capped at
//     min(pack limit, import limit - smoothed house net load - margin), water-filled, and the
//     same cap feeds the 'cheap hours enough?' test and the PV-reservation feasibility.
//
// The window is ALWAYS input_datetime start -> end, clamped to the current day by
// sensor.deadline_window. The pacing choice only decides WHERE inside that window the
// energy goes, so the deadline is honoured either way.
//
// All settings come from flow context, refreshed by the "Settings" group whenever one
// of them changes (and once a minute as a repair). Nothing is read from Home Assistant
// on this path - it runs on every P1 update, up to ~1 Hz.
const log = global.get('logger');
const cfg = flow.get('deadline_cfg') || {};
const d = msg.deadline || {};

// The settings snapshot is refreshed on every change and once every 30 s as a repair.
// If it ever stops arriving - HA restarting, the template failing, the websocket down -
// this loop must NOT keep commanding a charge from settings that may no longer be true.
// Anything older than five minutes is treated as "no settings", which lands in the
// fallback strategy, the same place an unconfigured window lands.
const CFG_MAX_AGE_MS = 5 * 60 * 1000;
const cfgAge = Number(cfg.stamp) ? (Date.now() - Number(cfg.stamp)) : Infinity;
const cfgStale = !cfg.window || cfgAge > CFG_MAX_AGE_MS;
if (cfgStale) {
    // Warn at most once a minute so a long outage does not fill the log.
    const lastWarn = Number(context.get('stale_warned')) || 0;
    if (Date.now() - lastWarn > 60000) {
        context.set('stale_warned', Date.now());
        node.warn(`[Deadline] settings snapshot is ${Number.isFinite(cfgAge) ? Math.round(cfgAge / 1000) + ' s old' : 'missing'} - falling back`);
    }
} else if (context.get('stale_warned')) {
    context.set('stale_warned', 0);
}

// ---------------------------------------------------------------------------------
// Settings
// ---------------------------------------------------------------------------------
const wAttr = (cfg.window && cfg.window.attributes) || {};
const bool = (v, dflt) => (v === undefined || v === null || v === '') ? dflt
    : (v === true || v === 'true' || v === 'on' || v === 'True');

const goal         = cfg.goal || "state of charge";
const alwaysFull   = (goal === "batteries are full");
const targetSoc    = alwaysFull ? 100 : Number(cfg.target_soc);
const targetEnergy = Number(cfg.target_energy);
const fallback     = cfg.fallback || "Self-consumption";
const pacing       = String(wAttr.pacing || "Spread evenly");
const holdAfter    = bool(cfg.hold_after_target, true);   // default ON
const reservePv    = bool(cfg.reserve_pv, false);         // default OFF
const pvForecastWh = Math.max(0, (Number(cfg.pv_forecast_kwh) || 0) * 1000);

// Window facts, all decided by Home Assistant so the Node-RED container's timezone
// cannot shift the window (this flow no longer parses a clock time itself).
const configuredWin = bool(wAttr.configured, false);
const inWindow      = bool(wAttr.in_window, false);
const minutesLeft   = Math.max(0, Number(wAttr.minutes_left) || 0);
// Only trust a well-formed HH:MM:SS; block boundaries are compared as strings.
const rawNow        = String(wAttr.now_hms || "");
const nowHms        = /^\d{2}:\d{2}:\d{2}$/.test(rawNow) ? rawNow : "";
// Drop anything malformed rather than letting one bad entry skew the pacing.
const blocks        = (Array.isArray(wAttr.blocks) ? wAttr.blocks : []).filter(b =>
    b && /^\d{2}:\d{2}:\d{2}$/.test(String(b.start)) && /^\d{2}:\d{2}:\d{2}$/.test(String(b.end))
    && Number(b.minutes) > 0);

// Live power and limits, already on the message from the Start flow.
const hasImportLimit = msg.grid_power_has_limit_import === true;
const importLimit    = Number(msg.grid_power_limit_import) || 0;
const maxChargeW     = Number(msg.batteries_max_charge_power) || 0;
const batteries      = Array.isArray(msg.batteries) ? msg.batteries : [];
const batteryChargeW = Number(msg.batteries_total_power) || 0;
const gridPowerW     = Number(msg.grid_power) || 0;
// grid = load - PV + battery_charge   ->   PV - load = battery_charge - grid
const pvSurplusW = batteryChargeW - gridPowerW;

// ---------------------------------------------------------------------------------
// v2: import limit - what the grid connection leaves for the packs.
// House net load (load - PV, floored at 0), smoothed with a ~10 min time constant so a
// kettle or oven does not reshape the plan; the live gridTargetW clamp below still
// catches short spikes. With the import limit off, only the pack limit applies.
// ---------------------------------------------------------------------------------
// SIGNED: load - PV. Negative when PV covers the house with surplus to spare - that surplus
// can go into the packs on top of the import limit. (It used to be floored at 0 here, which
// threw the PV surplus away: the cap stayed at importLimit - margin on a sunny afternoon.)
const houseNetW = -pvSurplusW;
const netEst = context.get('house_net_est') || { w: houseNetW, t: Date.now() };
const dtS = Math.min(60, Math.max(0, (Date.now() - Number(netEst.t)) / 1000));
netEst.w = (Number(netEst.w) || 0) + (1 - Math.exp(-dtS / 600)) * (houseNetW - (Number(netEst.w) || 0));
netEst.t = Date.now();
context.set('house_net_est', netEst);

const IMPORT_MARGIN_W = 0;         // was 150 W of headroom for the PID and load spikes; removed 2026-10-16 on request
const packCapW   = maxChargeW > 0 ? maxChargeW : Infinity;
// Two caps from the same import limit:
//   importCapW    - for PLANNING (the 'cheap hours enough?' test, the weighted plan, the PV
//                   feasibility). Counts house load but NOT a PV surplus: the plan covers
//                   blocks later today, e.g. one at 23:45, where there will be no sun.
//   importCapNowW - for the power commanded NOW: import limit - (load - PV) - margin, so a
//                   PV surplus right now adds to what the packs may take.
// The grid setpoint is still clamped at the import limit below, so if a cloud takes the PV
// away the PID drops the charge rather than the grid going over the limit.
const importCapW = (hasImportLimit && importLimit > 0)
    ? Math.max(0, importLimit - Math.max(0, netEst.w) - IMPORT_MARGIN_W) : Infinity;
const importCapNowW = (hasImportLimit && importLimit > 0)
    ? Math.max(0, importLimit - netEst.w - IMPORT_MARGIN_W) : Infinity;
const planCapW   = Math.min(packCapW, importCapW);
const nowCapW    = Math.min(packCapW, importCapNowW);
const importBinding = importCapNowW < packCapW;

// ---------------------------------------------------------------------------------
// v2: price-weighted pacing - per-quarter prices from sensor.deadline_window.quarters.
// ---------------------------------------------------------------------------------
const priceRatio = Math.max(1, Math.min(5, Number(cfg.price_ratio) || 1));
const toSec = hms => { const [h, m, s] = String(hms).split(':').map(Number); return h * 3600 + m * 60 + s; };
const allQuarters = (Array.isArray(wAttr.quarters) ? wAttr.quarters : []).filter(q =>
    q && /^\d{2}:\d{2}:\d{2}$/.test(String(q.start)) && /^\d{2}:\d{2}:\d{2}$/.test(String(q.end))
    && String(q.end) > String(q.start) && q.price !== null && q.price !== '' && Number.isFinite(Number(q.price)));
// Day-wide range: a quarter keeps its weight all day, whatever has already passed.
const qPrices = allQuarters.map(q => Number(q.price));
const pLo = qPrices.length ? Math.min(...qPrices) : 0;
const pHi = qPrices.length ? Math.max(...qPrices) : 0;

// Quarters still ahead, clipped to now, with fractional minutes.
function quartersAhead() {
    if (!nowHms) return [];
    const nowS = toSec(nowHms);
    return allQuarters.map(q => ({ ...q, mins: (toSec(q.end) - Math.max(toSec(q.start), nowS)) / 60 }))
        .filter(q => q.mins > 0);
}

// Share energyWh over qs in proportion to weight x minutes, water-filling at capW.
// Sum of P_i * mins_i / 60 == energyWh, unless every quarter ends at capW (infeasible).
function weightedPlan(qs, energyWh, capW) {
    const span = pHi - pLo;
    const w = qs.map(q => (priceRatio > 1 && span > 1e-6)
        ? 1 + (priceRatio - 1) * Math.min(1, Math.max(0, (pHi - Number(q.price)) / span)) : 1);
    const fixed = qs.map(() => null);
    let eLeft = energyWh;
    for (let pass = 0; pass <= qs.length; pass++) {
        let denom = 0;
        qs.forEach((q, i) => { if (fixed[i] === null) denom += w[i] * q.mins / 60; });
        if (denom <= 0) break;
        const c = Math.max(0, eLeft) / denom;
        const over = qs.map((_, i) => i).filter(i => fixed[i] === null && Number.isFinite(capW) && w[i] * c > capW);
        if (!over.length) return qs.map((_, i) => fixed[i] !== null ? fixed[i] : w[i] * c);
        over.forEach(i => { fixed[i] = capW; eLeft -= capW * qs[i].mins / 60; });
    }
    return qs.map((_, i) => fixed[i] !== null ? fixed[i] : capW);
}

// ---------------------------------------------------------------------------------
// Energy still required to reach the target
// ---------------------------------------------------------------------------------
let remainingWh = 0;
if (goal === "energy reserve") {
    const availE = Number(msg.batteries_available_energy) || 0;   // kWh
    remainingWh = Math.max(0, (targetEnergy - availE)) * 1000;
} else {
    batteries.forEach(b => {
        const soc = Number(b.soc) || 0;
        const socMax = Number(b.soc_max) || 100;
        const eMax = Number(b.energy_max) || 0;
        const tgt = Math.min(targetSoc, socMax);
        remainingWh += (Math.max(0, tgt - soc) / 100) * eMax * 1000;
    });
}
const remainingKwh = remainingWh / 1000;

// ---------------------------------------------------------------------------------
// "Target reached" is LATCHED, not re-tested every tick.
//
// Without this the flow hands over to the fallback the instant the target is met, the
// fallback discharges to cover the house, one second of that puts the shortfall back
// above tolerance, and the next tick charges it again - a ping-pong that runs for the
// rest of the window and buys the same energy over and over.
//
// The latch is keyed on the window + goal, so changing any of them starts a fresh
// deadline, and it clears when the window closes so tomorrow starts clean.
//   hold_after_target ON  -> stays reached for the rest of the window (a reserve built
//                            at 03:00 is still there at the 07:00 deadline).
//   hold_after_target OFF -> old behaviour, but with 0.30 kWh of hysteresis so it still
//                            cannot oscillate at tick rate.
// ---------------------------------------------------------------------------------
const REENTER_KWH = 0.30;
const winKey = [wAttr.start, wAttr.end, goal, targetSoc, targetEnergy].join('|');
const st = flow.get('deadline_state') || {};
if (st.key !== winKey || !inWindow) { st.key = winKey; st.reached = false; }
if (!st.reached && remainingKwh <= 0.05) st.reached = true;
if (st.reached && !holdAfter && remainingKwh > REENTER_KWH) st.reached = false;
flow.set('deadline_state', st);
const targetReached = st.reached;

// ---------------------------------------------------------------------------------
// Cheapest-hours selection.
//
// EVERY period marked cheap inside the window is used - not just enough of them to
// cover the energy. What the price-marks visualisation shows is exactly what gets
// charged, and the energy is paced across all of them, so the power per block (and the
// load on the grid connection) is as low as the deadline allows.
//
// Computed even when we are NOT charging, so the dashboard can show tonight's plan
// while it is still afternoon. Blocks are already clipped to [now, window end] on the
// current day, so every minute listed is a minute still ahead of us.
// ---------------------------------------------------------------------------------
// v2: capacity under BOTH limits, so the import limit can make the cheap hours 'too short'.
// No known cap (pack limit unread, import limit off) means no ceiling, not zero capacity:
// a 0 here made every set of cheap hours look 'too short' and sent the plan to spreading.
const perMinWh = Number.isFinite(planCapW) ? planCapW / 60 : Infinity;
// Both paced modes work off wAttr.blocks, which Home Assistant has already clipped to
// the minutes still ahead of us: the cheap periods under Dynamic, the Charge Deadline
// periods under Timed. "Spread evenly" (a manual window) has no blocks and paces on the
// wall clock instead.
const paced = (pacing === "Cheapest hours" || pacing === "Time slot");
const chosen = [];
let chosenMin = 0, capacityWh = 0;
if (paced && configuredWin) {
    for (const b of blocks) {
        const m = Math.max(0, Number(b.minutes) || 0);
        chosen.push(b); chosenMin += m; capacityWh += perMinWh * m;
    }
}
// +1 Wh of slack so a block that covers it exactly is not rejected by float noise.
const cheapEnough = chosenMin > 0 && (capacityWh + 1) >= remainingWh;
const inNow = b => nowHms && String(b.start) <= nowHms && nowHms < String(b.end);
const inChosen = chosen.some(inNow);

// ---------------------------------------------------------------------------------
// Mode
// ---------------------------------------------------------------------------------
let mode = "charge";
let requiredW = 0, gridTargetW = 0, pvShareW = 0, gridShareW = 0, shortageW = 0;
let statusText = "", dischargeDisabled = false, atMaxPower = false, planNote = "";

const goalConfigOk = (goal === "energy reserve") ? (targetEnergy > 0) : (targetSoc > 0);
const configOk = !cfgStale && goalConfigOk && batteries.length > 0 && configuredWin;
const targetLabel = (goal === "energy reserve") ? `${targetEnergy} kWh`
    : alwaysFull ? 'full (100%)' : `${targetSoc}%`;

if (cfgStale || !configOk || !inWindow || targetReached) {
    if (cfgStale) {
        mode = "fallback"; statusText = `Settings unavailable - ${fallback}`;
    } else if (!configuredWin) {
        mode = "fallback"; statusText = `No charge window set - ${fallback}`;
    } else if (!configOk) {
        mode = "fallback"; statusText = `Not configured - ${fallback}`;
    } else if (targetReached) {
        // Holding keeps discharge disabled, otherwise the reserve we just built is the
        // first thing the fallback spends.
        mode = holdAfter ? "hold" : "fallback";
        dischargeDisabled = holdAfter;
        statusText = holdAfter
            ? `Target ${targetLabel} reached - holding until deadline`
            : `Target ${targetLabel} reached - ${fallback}`;
    } else {
        mode = "fallback"; statusText = `Outside window - ${fallback}`;
    }
} else {
    // ------------------------------------------------------------------------------
    // Inside the window with energy still to add. Decide how much time we are allowed
    // to spread it over.
    // ------------------------------------------------------------------------------
    let planMinutes = minutesLeft;      // minutes we intend to charge in
    let waiting = false;                // in a gap between cheap blocks
    let weighted = false;               // v2: price-weighted pacing applies
    let planBaseWh = remainingWh;       // energy this plan has to place in planMinutes

    if (pacing === "Cheapest hours") {
        // Always pace over the cheap minutes still ahead, so the target lands at the end of
        // the last cheap block. (2026-10-16: when the cheap hours could not carry it at the
        // cap, this used to abandon the blocks and spread flat over the wall clock - ~1 kW
        // everywhere, expensive gaps included, while the cheap blocks went under-used.)
        if (chosenMin <= 0) {
            planNote = " - no cheap hours, spreading";
        } else if (inChosen) {
            planMinutes = chosenMin;           // pace across the cheap minutes only
            weighted = priceRatio > 1 && cheapEnough;   // v2; at the cap there is nothing to weight
            planNote = cheapEnough
                ? ` - ${chosen.length} cheap block${chosen.length === 1 ? '' : 's'}`
                : ` - cheap hours too short, max power in ${chosen.length} block${chosen.length === 1 ? '' : 's'}`;
        } else if (cheapEnough) {
            waiting = true;                    // cheap hours are enough, just not now
        } else {
            // In a gap, and the cheap blocks ahead cannot carry it even at the cap: buy only
            // the overflow here, spread over the gap minutes left. The blocks take the rest.
            const gapMin = Math.max(0, minutesLeft - chosenMin);
            if (gapMin > 0) {
                planMinutes = gapMin;
                planBaseWh = Math.max(0, remainingWh - capacityWh);
                planNote = ` - cheap hours too short, ${(planBaseWh / 1000).toFixed(1)} kWh in the gap`;
            } else {
                planNote = " - cheap hours too short, spreading";
            }
        }
    } else if (pacing === "Time slot") {
        // The Timed strategy only dispatches Charge Deadline while one of ITS OWN periods
        // is running, so the minutes between two periods can never be charged in. Pacing
        // over the wall clock to the end of the last period spreads the energy across
        // those dead minutes: the rate inside each period comes out too low, nothing makes
        // up for it in the gap, and the whole shortfall lands on the final period - at max
        // power, or missed. So pace over the period minutes still ahead instead, exactly
        // as Cheapest hours paces over its blocks.
        //
        // No 'cheapEnough' test and no waiting, which is where this differs from cheap
        // hours. If the periods cannot carry the energy there is no cheaper alternative to
        // fall back to - requiredW is clamped to the pack limit below and the shortage is
        // reported, which is the honest answer. And this flow only runs while a period is
        // active, so a tick outside one means the times moved under us: spreading over the
        // window is a better guess than idling against a deadline.
        if (chosenMin > 0) {
            planMinutes = chosenMin;
            planNote = ` - ${chosen.length} period${chosen.length === 1 ? '' : 's'}`;
        } else {
            planNote = " - no period time left, spreading";
        }
    }

    if (waiting) {
        // Hand back to the fallback until the next cheap block opens. Discharge stays
        // allowed: anything the house takes now is simply re-bought at the cheap price,
        // and the plan recomputes from the real shortfall on every tick.
        mode = "idle";
        const nextBlock = blocks
            .filter(b => nowHms && String(b.start) > nowHms)
            .sort((a, b) => String(a.start) < String(b.start) ? -1 : 1)[0];
        statusText = nextBlock
            ? `Waiting for cheap hours (${String(nextBlock.start).slice(0, 5)}) - ${remainingKwh.toFixed(1)} kWh to go`
            : `Waiting for cheap hours - ${remainingKwh.toFixed(1)} kWh to go`;
    } else {
        mode = "charge";
        dischargeDisabled = true;             // don't fight the fill

        // Optionally let the PV that is still forecast for today do part of the work,
        // instead of buying it now and having no room left when the sun arrives.
        // Only while there is real slack: once the job barely fits in the time left at
        // full power, plan for all of it and let measured PV reduce the grid draw.
        const feasibleWh = (Number.isFinite(planCapW) && planCapW > 0) ? planCapW * (minutesLeft / 60) : 0;
        let planWh = planBaseWh;
        if (reservePv && pvForecastWh > 0 && feasibleWh > 0 && remainingWh < feasibleWh * 0.6) {
            const reserved = Math.min(pvForecastWh, planBaseWh);
            planWh = Math.max(0, planBaseWh - reserved);
            if (reserved > 50) planNote += ` - ${(reserved / 1000).toFixed(1)} kWh left to PV`;
        }

        const avgW = planMinutes > 0 ? planWh / (planMinutes / 60) : 0;
        requiredW = avgW;
        if (weighted) {
            // v2: the power of the quarter we are in, from a plan over the quarters ahead.
            // No matching quarter (data gap) -> stay on the flat average.
            const qs = quartersAhead();
            const idx = qs.findIndex(q => String(q.start) <= nowHms && nowHms < String(q.end));
            if (idx >= 0) {
                requiredW = weightedPlan(qs, planWh, planCapW)[idx];
                planNote += ` - price x${priceRatio}, avg ${Math.round(avgW / 10) * 10} W`;
            }
        }
        if (Number.isFinite(nowCapW) && requiredW > nowCapW) { requiredW = nowCapW; atMaxPower = true; }

        // Grid setpoint for the Self-consumption PID: B = G + PV_surplus, so G = B - PV_surplus
        // = battery charge + house load - PV.
        // The pack limit is NOT applied here: it caps the BATTERY power, and requiredW is
        // already capped at planCapW (<= pack limit) above. Capping the GRID setpoint at the
        // pack limit took the house load off the charge: max charge 4 kW with the house on
        // 1 kW gave a 4 kW grid target and only 3 kW into the packs (fixed 2026-10-16).
        // The import limit IS a grid quantity, so that clamp stays.
        gridTargetW = Math.max(0, requiredW - pvSurplusW);
        if (hasImportLimit && importLimit > 0) gridTargetW = Math.min(gridTargetW, importLimit);

        // Measured split of the charge actually happening.
        const actualChargeW = Math.max(0, batteryChargeW);
        pvShareW = Math.max(0, Math.min(pvSurplusW, actualChargeW));
        gridShareW = Math.max(0, actualChargeW - pvShareW);

        // "Shortage" means: we are already against a limit and still below plan. Below
        // the limits a gap is just the PID catching up, so it is not reported.
        // NOTE: pvShare + gridShare = the ACTUAL charge power. It only adds up to
        // requiredW while a limit is binding - the bar shows what is happening, not
        // what was planned.
        const CAP_TOL_W = 50;
        const importCapped = hasImportLimit && importLimit > 0 && gridPowerW >= (importLimit - CAP_TOL_W);
        const chargeCapped = maxChargeW > 0 && actualChargeW >= (maxChargeW - CAP_TOL_W);
        shortageW = (importCapped || chargeCapped) ? Math.max(0, requiredW - actualChargeW) : 0;

        const r10 = v => Math.round(v / 10) * 10;
        requiredW = r10(requiredW);   // 10 W: keeps the status string (and the change gate) still
        gridTargetW = Math.round(gridTargetW);
        pvShareW = r10(pvShareW); gridShareW = r10(gridShareW); shortageW = r10(shortageW);

        const rH = Math.floor(planMinutes / 60), rM = Math.round(planMinutes % 60);
        statusText = `Charging ${remainingKwh.toFixed(1)} kWh in ${rH}h${String(rM).padStart(2, '0')} @ ${requiredW} W`;
        if (shortageW > 0) statusText += ` - short ${shortageW} W`;
        if (atMaxPower) statusText += importBinding ? ' - at import limit' : ' - at max power';
        statusText += planNote;
        log(this, `[Deadline v2] ${remainingKwh.toFixed(2)} kWh, ${planMinutes} min of charge time, avg ${requiredW} W, PV surplus ${Math.round(pvSurplusW)} W -> grid target ${gridTargetW} W${planNote}`);
    }
}

// ---------------------------------------------------------------------------------
// Store for delegation + UI. Everything written to an input_number is clamped to its
// configured range - an out-of-range set_value throws and would abort the strategy.
// ---------------------------------------------------------------------------------
const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, Number(v) || 0));

d.mode = mode;
d.pacing = pacing;
d.discharge_disabled = dischargeDisabled;
d.fallback = fallback;
d.grid_target = clamp(gridTargetW, 0, 25000);
d.required_power = clamp(requiredW, 0, 25000);
d.grid_share = clamp(gridShareW, 0, 25000);
d.pv_share = clamp(pvShareW, 0, 25000);
d.shortage = clamp(shortageW, 0, 25000);
d.pv_surplus = Math.round(pvSurplusW);
d.battery_power = Math.round(batteryChargeW);
d.grid_power = Math.round(gridPowerW);
d.remaining_energy = clamp(Math.round(remainingKwh * 100) / 100, 0, 1000);
// CHARGE minutes left to the deadline: the sum of the blocks still ahead, not the wall
// clock to the end of the last one. The at-risk sensor and the estimated SoC multiply
// this by a charge power, so the expensive gaps between blocks must not count - with two
// blocks in a day they made the deadline look safer than it was (fixed 2026-10-07).
// Only where the flow really paces on the blocks: under Cheapest hours with too few
// cheap minutes it spreads over the whole window (gaps included), so then it is the
// wall clock again. Manual window has no blocks -> wall clock.
const spreadingWholeWindow = pacing === "Cheapest hours" && !cheapEnough;
const chargeMinutes = (paced && chosenMin > 0 && !spreadingWholeWindow) ? chosenMin : minutesLeft;
d.charge_minutes = Math.round(chargeMinutes);
d.remaining_minutes = clamp(Math.round(mode === "fallback" && !inWindow ? 0 : chargeMinutes), 0, 1440);
d.status = String(statusText).slice(0, 255);
msg.deadline = d;

node.status({
    fill: mode === "charge" ? "green" : mode === "idle" ? "blue" : mode === "hold" ? "yellow" : "grey",
    shape: "dot", text: statusText
});
return msg;

const log = global.get('logger');
const d = msg.deadline || {};
// Drive the Self-consumption PID to the computed grid setpoint
msg.target = "Self-consumption";
msg.house_target_grid_consumption_in_w = Number(d.grid_target) || 0;
// Don't discharge while we are trying to fill the battery
RED.util.setMessageProperty(msg, "advanced_settings.discharge_disabled", true, true);
// Show "Charge Deadline" on the HBC strategy display instead of the sub-strategy
RED.util.setMessageProperty(msg, "strategy.display", "Charge Deadline", true);
log(this, `**Charge Deadline** -> grid target ${msg.house_target_grid_consumption_in_w} W`);
return msg;

const log = global.get('logger');
const d = msg.deadline || {};
const fb = d.fallback || "Self-consumption";
msg.target = fb;
// For NoM fallback, force target grid consumption to 0 (avoid a stale setpoint)
if (fb === "Self-consumption") { msg.house_target_grid_consumption_in_w = 0; }

// HOLD: the target was reached before the deadline. Hand the house back to the fallback
// strategy but keep discharge blocked, otherwise the reserve we just built is the first
// thing that gets spent - and the old code then re-bought it, tick after tick.
// IDLE: "Cheapest hours" pacing, waiting for the next cheap block. Discharge stays
// allowed there; whatever the house takes now is simply re-bought at the cheap price.
if (d.discharge_disabled) {
    RED.util.setMessageProperty(msg, "advanced_settings.discharge_disabled", true, true);
}
// Keep showing who is in charge while holding or waiting; a plain fallback (outside the
// window, or not configured) is more informative as the sub-strategy's own name.
if (d.mode === "hold" || d.mode === "idle") {
    RED.util.setMessageProperty(msg, "strategy.display", "Charge Deadline", true);
}
log(this, `**Charge Deadline** ${d.mode || 'fallback'} -> ${fb}`);
return msg;

// Throttle the writes to Home Assistant.
// The strategy runs on every P1 update (up to 1x/s). Writing seven input_number helpers
// that often floods the recorder, so only write when something actually changed, and at
// most once per gate interval.
//
// The values are QUANTISED before comparing. Without that the gate never matched: the
// status string carried two decimals of kWh and a watt-resolution power figure, so the
// snapshot differed on practically every tick and the rate limit was the only thing
// throttling anything - about 5 000 service calls an hour, every one of them recorded.
//
// TWO GATES:
//   output 1 (fast, 1 s)  - PV share / grid share / shortage. These three drive the
//                           `distribution` bar on the Charge Deadline view, which should
//                           track the PID live. Exclude them from the recorder
//                           (see configuration.yaml) or the database pays for it.
//   output 2 (slow, 10 s) - required power, remaining energy/minutes and status. These
//                           are planning figures; a 1 s cadence buys nothing.
// A mode change is written out on both gates immediately, regardless of interval.
const FAST_MIN_INTERVAL_MS = 1000;
const SLOW_MIN_INTERVAL_MS = 10000;

const d = msg.deadline || {};
const q = (v, step) => Math.round((Number(v) || 0) / step) * step;

const fastSnapshot = JSON.stringify([
    d.mode,
    q(d.pv_share, 25), q(d.grid_share, 25), q(d.shortage, 25)
]);
const slowSnapshot = JSON.stringify([
    d.mode, d.status,
    q(d.required_power, 25),
    q(d.remaining_energy, 0.05), q(d.remaining_minutes, 1)
]);

const nowMs = Date.now();

// A mode change bypasses both intervals.
const lastMode = context.get('ui_last_mode');
const modeChanged = lastMode === undefined || lastMode !== d.mode;
context.set('ui_last_mode', d.mode);

// Generic gate: returns true when this branch should write.
const due = (key, snapshot, interval) => {
    if (context.get('ui_last_' + key) === snapshot) return false;      // nothing changed
    const lastTime = Number(context.get('ui_last_time_' + key)) || 0;
    if (!modeChanged && (nowMs - lastTime) < interval) return false;   // too soon
    context.set('ui_last_' + key, snapshot);
    context.set('ui_last_time_' + key, nowMs);
    return true;
};

const fastDue = due('fast', fastSnapshot, FAST_MIN_INTERVAL_MS);
const slowDue = due('slow', slowSnapshot, SLOW_MIN_INTERVAL_MS);

if (!fastDue && !slowDue) return null;

node.status({
    fill: "blue", shape: "dot",
    text: `${fastDue ? "bar" : ""}${fastDue && slowDue ? " + " : ""}${slowDue ? "plan" : ""} ${new Date(nowMs).toLocaleTimeString()}`
});

return [
    fastDue ? RED.util.cloneMessage(msg) : null,
    slowDue ? RED.util.cloneMessage(msg) : null
];

const handle = global.get('unhandledException');
if (handle) handle(this);
node.status({ fill: 'red', shape: 'dot', text: `${(msg.error && msg.error.message) || 'error'} @ ${new Date().toLocaleTimeString()}` });
// Only a link-call can be returned to; anything else (the settings group) stops here.
if (msg._linkSource) { return msg; }
return null;

