func:
// Publish the settings snapshot to flow context.
// The control path reads ONLY this - it runs on every P1 update (up to ~1 Hz) and used to
// walk seven api-current-state nodes in series to fetch values that change when the user
// touches a dashboard, i.e. almost never.
//
// A bad render keeps the PREVIOUS snapshot rather than blanking it, so one failed refresh
// is harmless; Compute plan gives up on its own once the snapshot goes stale (5 minutes).
const cfg = msg.deadline_cfg;
const ok = cfg && typeof cfg === 'object' && cfg.window
    && typeof cfg.window === 'object' && cfg.window.attributes;
if (!ok) {
    node.status({ fill: 'red', shape: 'ring', text: `settings render failed ${new Date().toLocaleTimeString()}` });
    node.warn('[Deadline] settings template returned nothing usable - keeping the previous snapshot');
    return null;
}
cfg.stamp = Date.now();
flow.set('deadline_cfg', cfg);
const a = cfg.window.attributes;
node.status({ fill: 'grey', shape: 'dot', text: `${cfg.goal || '?'} / ${a.pacing || '?'} @ ${new Date().toLocaleTimeString()}` });
return null;                         // a settings refresh never continues into the flow

// Logger, usage: log(this, "");
const log = global.get('logger');
log(this, "Charge at **max. power**");

// INPUT
let batteries = msg.batteries;
let solution_array = [];

// build solution
msg.batteries.forEach(battery => {
    const calculatedPower = Number(battery.charging_max);

    solution_array.push({
        id: battery.id,
        mode: "charge",
        power: calculatedPower
    });

});

// return solution
msg.solutions = solution_array;
return msg;

// Logger, usage: log(this, "");
const log = global.get('logger');

// Which sub-strategy to use
msg.target = "Self-consumption";

// Grid power limit
const targetGridPower = parseInt(msg.grid_power_limit_import);

// Set target grid consumption for the PID controller
msg.house_target_grid_consumption_in_w = targetGridPower;
// tell PID to avoid discharge solutions during charging.
RED.util.setMessageProperty(msg,"advanced_settings.discharge_disabled",true,true);

// --- Feed-forward start (2026-10-15) ---------------------------------------------------
// The PID only reaches the import limit through its integral term, which takes a minute or
// more with a small Ki. When regulated charging STARTS, jump straight to the charge power
// that should bring grid import to the limit: current battery power + (limit - grid power),
// minus a small margin. That power is held for FF_HOLD_MS so the batteries can respond; the
// PID step (Self-consumption flow) seeds its integral with it, then resumes normal control
// and trims the last watts. Set FF_ENABLED = false to go back to the old behaviour.
const FF_ENABLED = true;
const FF_HOLD_MS = 10000;      // how long the start power is held (battery response time)
const FF_MARGIN_W = 150;       // stay this far below the import limit, PID adds the rest
const FF_RESTART_MS = 30000;   // a pause longer than this counts as a new charge session

const now = Date.now();
const lastRun = context.get("ff_last_run") || 0;
let ff = context.get("ff") || null;

if (FF_ENABLED && now - lastRun > FF_RESTART_MS) {
    const gridPower = Number(msg.grid_power) || 0;              // import positive
    const batteryPower = Number(msg.batteries_total_power) || 0; // charging positive
    const maxCharge = Number(msg.batteries_max_charge_power) || 0;
    const gap = targetGridPower - gridPower;
    let ffPower = batteryPower + gap - FF_MARGIN_W;
    if (maxCharge > 0) ffPower = Math.min(ffPower, maxCharge);
    ffPower = Math.round(ffPower);

    if (Number.isFinite(ffPower) && ffPower > 0 && gap > FF_MARGIN_W) {
        ff = { power: ffPower, until: now + FF_HOLD_MS };
        log(this, `**Feed-forward start** ${ffPower} W for ${FF_HOLD_MS / 1000} s (grid ${Math.round(gridPower)} W, battery ${Math.round(batteryPower)} W, limit ${targetGridPower} W)`);
    } else {
        ff = null;
    }
}
context.set("ff_last_run", now);

if (ff && now < ff.until) {
    msg.pid_feedforward_w = ff.power;
    node.status({ fill: "blue", shape: "dot", text: `feed-forward ${ff.power} W, ${Math.ceil((ff.until - now) / 1000)} s` });
} else {
    ff = null;
    node.status({ fill: "green", shape: "dot", text: `regulated to ${targetGridPower} W` });
}
context.set("ff", ff);

// Finally
log(this, `**Regulated** charging. Target grid power: ${Math.floor(targetGridPower)} W`);
return msg;

const log = global.get("logger");

// Unkown export goal
log(this, `**${msg.charge.goal}**; Charge goal not recognized. Fallback to **Full Stop**`,"warn");

// Full stop
msg.target = "Full stop";

return msg;

// 1. Get the custom logger from global context
const log = global.get("logger");
log(this,`Charge until: ${msg.charge.goal}`);

// 2. Extract energy level from msg (default to 0 if property is missing)
const energy_remaining = Number(RED.util.getMessageProperty(msg, "batteries_available_energy")) || 0;
var energy_threshold = Number(RED.util.getMessageProperty(msg,"charge.threshold_energy"));
if (energy_threshold === undefined || energy_threshold <= 0){
    log(this,`Desired energy reserve invalid '${energy_threshold}' kWh. I've set it to ${Number(msg.batteries_max_energy).toFixed(1)} kWh`,"warn");
    energy_threshold = Math.floor(Number(msg.batteries_max_energy)*10)/10;
}

// 3. Logic: Determine if energy level is at or below zero
if (energy_remaining >= energy_threshold) {
    msg.charge.threshold_reached = true;

    // User friendly feedback via the custom logger
    log(this, `[STOP] Energy reserve at ${energy_remaining.toFixed(1)} / ${energy_threshold.toFixed(1)} kWh`, 'info');
} else {
    msg.charge.threshold_reached = false;

    // User friendly feedback via the custom logger
    log(this, `[OK] Energy reserve at ${energy_remaining.toFixed(1)} / ${energy_threshold.toFixed(1)} kWh.`, 'info');
}

// 4. Update node status for visual feedback in the editor
node.status({ 
    fill: msg.charge.threshold_reached ? "red" : "green", 
    shape: "dot", 
    text: `Threshold reached: ${msg.charge.threshold_reached}` 
});

return msg;

// 1. Get the custom logger from global context
const log = global.get("logger");
log(this, `Charge until: ${msg.charge.goal}`);

// 2. Extract average SoC and desired SoC level
let batteries = msg.batteries;
let soc_avg = 0;
let count = 0; // could use msg.battery_count
batteries.forEach(battery => {
    soc_avg += battery.soc;
    count++;
});
// 2.1 Current avg. SoC
soc_avg = Math.round(soc_avg / count * 100) / 100;
// 2.2 Charge until SoC (100% as fallback)
var soc_threshold = Number(RED.util.getMessageProperty(msg,"charge.threshold_soc"));
if (soc_threshold === undefined || soc_threshold < 11){
    log(this, `Desired SoC not set correctly '${soc_threshold}' %. I've set it to 100%.`,"warn");
    soc_threshold = 100;
}

// 3. Logic: Determine if SoC level is at or above desired level
if (soc_avg >= soc_threshold) {
    msg.charge.threshold_reached = true;

    // User friendly feedback via the custom logger
    log(this, `[STOP] Average SoC at ${soc_avg.toFixed(1)}/${soc_threshold.toFixed(1)} %.`, 'info');
} else {
    msg.charge.threshold_reached = false;

    // User friendly feedback via the custom logger
    log(this, `[OK] Average SoC at ${soc_avg.toFixed(1)}/${soc_threshold.toFixed(1)} %.`, 'info');
}

// 4. Update node status for visual feedback in the editor
node.status({
    fill: msg.charge.threshold_reached ? "red" : "green",
    shape: "dot",
    text: `Threshold reached: ${msg.charge.threshold_reached}`
});

return msg;

// 1. Get the custom logger from global context
const log = global.get("logger");
log(this,`Charge until: ${msg.charge.goal}`);

// 2. Extract energy level from msg (and handle missing properties)
const energy_remaining = Number(RED.util.getMessageProperty(msg, "batteries_available_energy")) || 0;
const energy_max = Number(RED.util.getMessageProperty(msg, "batteries_max_energy")) || 0;
if(energy_max == 0) log(this,`Batteries max energy missing! ${msg.batteries_max_energy}`);
// 2.1 Check if every battery's SoC is at or over the max
const isAtMax = msg.batteries.every(battery => battery.soc >= battery.soc_max);

// 3. Logic: Determine if energy level is over or near 99.9% of max eneregy
if (isAtMax) {
    msg.charge.threshold_reached = true;

    // User friendly feedback via the custom logger
    log(this, `[STOP] All batteries are full or at SoC_max_ (${energy_remaining} kWh).`, 'info');
} else {
    msg.charge.threshold_reached = false;

    // User friendly feedback via the custom logger
    log(this, `[OK] Battery level ${energy_remaining.toFixed(2)} kWh below ${energy_max.toFixed(2)} kWh.`, 'info');
}

// 4. Update node status for visual feedback in the editor
node.status({ 
    fill: msg.charge.threshold_reached ? "red" : "green", 
    shape: "dot", 
    text: `Threshold reached: ${msg.charge.threshold_reached}` 
});

return msg;

// Which strategy to run after the goal is reached
const goal = msg.charge.goal_reached_strategy || "Charge PV";
msg.target = goal;
return msg;

const log = global.get("logger");

if(msg.charge.threshold_reached){
    log(this,`Stop charging, Charge until ${msg.charge.goal} reached.`);
} else {
    log(this,`Continue charging.`);
}

return msg;

// Lower bound
let output = msg.charge.threshold_energy || 0; // kWh
output = Math.max(output, 0);

// Upper bound
output = Math.min(output, msg.batteries_max_energy);

node.status({fill:"blue",shape:"dot",text:`${output}`});

// Output
msg.payload = Math.round(output * 100) / 100; // 2 decimals
return msg;

// Log unhandled exception
const handle = global.get('unhandledException');
if(handle) handle(this);

// Check origin of msg execution
if (msg._linkSource) {
    return msg; // Origin: some other flow
} else {
    return null; // Origin: this flow. Stop to prevent 'Missing return' warning
}

// 1. Get the custom logger from global context
const log = global.get("logger");
log(this, `Charge using: ${msg.charge.goal}`);

// 2. Energy levels and solar forecast from msg (default to 0 if property is missing)
const energy_available = Number(RED.util.getMessageProperty(msg, "batteries_available_energy")) || 0; // kWh
const energy_max = Number(RED.util.getMessageProperty(msg, "batteries_max_energy")) || 0; // kWh
const solar_threshold_low = Number(RED.util.getMessageProperty(msg, "charge.solar_threshold_low")) || 0; // kWh
const solar_forecast = Number(RED.util.getMessageProperty(msg,"charge.solar_forecast_today")) || 0; // kWh

// 2.1 Desired charge level, considering the expected solar energy
const solar_surplus = Math.max(solar_forecast - solar_threshold_low, 0); // 0 or greater
const energy_desired = Math.max(energy_max - solar_surplus, 0); // 0 or greater
if (solar_surplus == 0) {
    log(this, `No solar surplus today. Forecast ${solar_forecast.toFixed(1)} kWh, with ${solar_threshold_low.toFixed(1)} kWh used by home.`);
}
if (energy_max == 0) log(this, `Batteries max energy unavailable!`, "warn");

// 3. Logic: is charging required or is the charging threshold_reached
if (energy_available >= energy_desired) {
    // Done
    msg.charge.threshold_reached = true;
    // Explain
    log(this, `[STOP] ${energy_available.toFixed(1)} battery + ${solar_surplus.toFixed(1)} solar = ok`, 'info');
} else {
    // Not ready
    msg.charge.threshold_reached = false;
    // Explain
    log(this, `[CHARGE] From ${energy_available.toFixed(1)} -> ${energy_desired.toFixed(1)} kWh.`, 'info');
}

// 4. Update node status for visual feedback in the editor
node.status({
    fill: msg.charge.threshold_reached ? "red" : "green",
    shape: "dot",
    text: `Threshold reached: ${msg.charge.threshold_reached} @ ${energy_desired.toFixed(1)} kWh`
});

// OUTPUT
msg.charge.threshold_energy = Number(energy_desired);
msg.payload = Number(energy_desired);
return msg;

// logger, usage: log(this, "");
const log = global.get('logger');

// 1.  Input
const minDeltaCents = parseInt(RED.util.getMessageProperty(msg, "dynamic.min_delta_cents")) || 0;
// Per-day caps on the number of LOW / HIGH marks, expressed in hours.
// 0 (or missing/invalid/negative) means no limit.
const cheapestHrs = parseFloat(RED.util.getMessageProperty(msg, "dynamic.cheapest_hrs")) || 0;
const expensiveHrs = parseFloat(RED.util.getMessageProperty(msg, "dynamic.expensive_hrs")) || 0;
const dataAll = RED.util.getMessageProperty(msg, "dynamic.data_all");

if (!dataAll || !Array.isArray(dataAll.list) || dataAll.list.length === 0) {
    log(this, "Price list missing or empty", "warn");
    node.status({ fill: "red", shape: "ring", text: "No price data" });
    return null;
}

const STRATEGY = {
    HIGH: RED.util.getMessageProperty(msg, "dynamic.strategy_expensive") || "Self-consumption",
    LOW: RED.util.getMessageProperty(msg, "dynamic.strategy_cheapest") || "Charge",
    NEUTRAL: RED.util.getMessageProperty(msg, "dynamic.strategy_default") || "Charge PV",
};

// 2.  Build interval timestamps
// Each datapoint covers (hours / datapoints) hours.
const prices = dataAll.list; // cents/kWh — already converted by "Convert price" node
const n = prices.length;
const startTime = new Date(dataAll.start);
const intervalMs = (dataAll.hours / dataAll.datapoints) * 3_600_000;

// 3.  Mark intervals: pair extremes inward — independently per calendar day
//
// Pairing runs separately within each local calendar day, so today's marks
// don't shift when tomorrow's prices arrive. Pair detection is one-to-one
// (each candidate HIGH is matched against one candidate LOW), but the
// per-day cheapest_hrs / expensive_hrs caps may suppress one side of a
// detected pair — so the final marks can be asymmetric (e.g. 2 LOW + 1 HIGH
// in a day if expensive_hrs caps HIGH at 1). The minDelta threshold
// accounts for round-trip efficiency and other losses, so a pair is only
// considered viable when its spread covers the loss.
//
// Method (Extreme-Pair Matching, O(n log n)):
//   1. Sort intervals by price, keep original time-index for re-mapping.
//   2. Two pointers walk inward from the extremes — `lo` from the cheapest
//      unmatched, `hi` from the most-expensive unmatched.
//   3. If the spread between them clears minDelta: mark them, advance both.
//   4. If it does not clear minDelta: the cheapest unmatched LOW paired
//      with the most-expensive unmatched HIGH yields the largest spread
//      still achievable. If even that fails, no remaining pair can satisfy
//      the threshold, so we stop.
//
// This algorithm prefers to mark the truly extreme
// hours (highest-priced as HIGH, lowest-priced as LOW). On well-behaved
// daily curves this produces the same number of pairs as 
// other algorithm variants; but in tight cases it can produce one or two fewer
// pairs. Why choose this version? It marks the price peaks/troughs the user
// would intuitively expect, which is good for user confidence and acceptance of the strategy. It is also efficient and straightforward to implement, without needing complex data structures or backtracking. 
// The main goal is to identify a set of HIGH and LOW intervals that are economically justified by their price spread, while keeping the logic transparent and explainable to the user.

// Note:
// It is up to the user to set minDelta appropriately for their system's efficiency and other costs, to ensure that marked cycles are truly beneficial.
// Also the user can pick strategies that reflect their preferences for what to do during LOW and HIGH intervals, e.g. prioritising self-consumption during HIGH intervals, or selling back to the grid if allowed and profitable.
// This makes optimisation flexible and user-configurable, while still being based on a clear economic rationale.
// However, the algorithm does not attempt to find the optimal global pairing (which would be more complex), but rather a good local pairing that is computationally efficient and easy to understand.

/**
 * @typedef {{ start: Date, end: Date, price: number, mark: 'high'|'low'|null, is_now: boolean }} Interval
 * @type {Interval[]}
 */
const intervals = new Array(n);
for (let i = 0; i < n; i++) {
    const iStart = new Date(startTime.getTime() + i * intervalMs);
    const iEnd = new Date(iStart.getTime() + intervalMs);
    intervals[i] = { start: iStart, end: iEnd, price: prices[i], mark: null, is_now: false };
}

// Group interval indices by local calendar day (key = Y-M-D in local TZ).
const dayBuckets = new Map();
for (let i = 0; i < n; i++) {
    const d = intervals[i].start;
    const key = `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
    let bucket = dayBuckets.get(key);
    if (!bucket) { bucket = []; dayBuckets.set(key, bucket); }
    bucket.push(i);
}

// Convert per-day hour caps to per-day interval counts.
// intervalsPerHour = datapoints / hours (e.g. 4 for 15-min intervals).
// 0 hrs => Infinity (no cap). Negatives are treated as 0 (no cap).
const intervalsPerHour = dataAll.datapoints / dataAll.hours;
const maxLowPerDay = cheapestHrs > 0 ? Math.round(cheapestHrs * intervalsPerHour) : Infinity;
const maxHighPerDay = expensiveHrs > 0 ? Math.round(expensiveHrs * intervalsPerHour) : Infinity;

// Per dag de markeringen zetten.
let fullPairCount = 0;   // pairs where BOTH sides were marked (a complete cycle)
let lowMarkCount = 0;    // total LOW marks across all days
let highMarkCount = 0;   // total HIGH marks across all days
for (const dayIndices of dayBuckets.values()) {
    // This day's indices sorted ascending by price (stable on ties).
    const sortedIdx = [...dayIndices].sort((a, b) => prices[a] - prices[b]);
    let lo = 0;
    let hi = sortedIdx.length - 1;
    let lowMarkedToday = 0;
    let highMarkedToday = 0;
    while (lo < hi) {
        const loIdx = sortedIdx[lo];
        const hiIdx = sortedIdx[hi];
        if (prices[hiIdx] - prices[loIdx] >= minDeltaCents) {
            const markLow = lowMarkedToday < maxLowPerDay;
            const markHigh = highMarkedToday < maxHighPerDay;
            // Both caps reached on this day — no more useful work here.
            if (!markLow && !markHigh) break;
            if (markLow) {
                intervals[loIdx].mark = 'low';
                lowMarkedToday++;
                lowMarkCount++;
            }
            if (markHigh) {
                intervals[hiIdx].mark = 'high';
                highMarkedToday++;
                highMarkCount++;
            }
            if (markLow && markHigh) fullPairCount++;
            lo++; hi--;
        } else {
            // sortedIdx[lo] is the cheapest unmatched within this day,
            // sortedIdx[hi] the most-expensive. Their spread is the largest
            // still possible today — if it falls below minDelta, no further
            // pair on this day can satisfy the threshold.
            break;
        }
    }
}

// 4.  Determine current strategy
const now = new Date();
const currentInterval = intervals.find(iv => now >= iv.start && now < iv.end);
if (currentInterval) currentInterval.is_now = true;
const currentMark = currentInterval ? currentInterval.mark : null;

const strategy =
    currentMark === 'high' ? STRATEGY.HIGH :
        currentMark === 'low' ? STRATEGY.LOW :
            STRATEGY.NEUTRAL;

const strategyMark = 
    currentMark === 'high' ? 'Expensive' :
        currentMark === 'low' ? 'Cheap' :
            'Regular';


// 5.  Store results
RED.util.setMessageProperty(msg,"dynamic.data_all.list_marked",intervals,true);
RED.util.setMessageProperty(msg, "dynamic.data_all.mark_now", strategyMark, true);
RED.util.setMessageProperty(msg,"dynamic.strategy",strategy);
flow.set("dynamic_strategy", strategy); // this is the strategy executed when dynamic strategy is active, see the 'Execute' section of this flow.

// 6.  Explain
// Extract and sort marked intervals to pair them correctly for profit analysis
const lowPrices = intervals
    .filter(iv => iv.mark === 'low')
    .map(iv => iv.price)
    .sort((a, b) => a - b); // Cheapest first
const highPrices = intervals
    .filter(iv => iv.mark === 'high')
    .map(iv => iv.price)
    .sort((a, b) => b - a); // Most expensive first

// Only calculate spread over actual completed cycles (pairs)
let grossSpread = 0;
for (let i = 0; i < fullPairCount; i++) {
    grossSpread += (highPrices[i] - lowPrices[i]);
}
const netSpread = grossSpread - (fullPairCount * minDeltaCents);
const markedCount = lowMarkCount + highMarkCount;

// 6a. Average spread per full cycle (pair) today
const avgGrossSpread = fullPairCount > 0 ? Math.round(grossSpread / fullPairCount) : 0;
const avgNetSpread = fullPairCount > 0 ? Math.round(netSpread / fullPairCount) : 0;
RED.util.setMessageProperty(msg, "dynamic.data_all.gross_spread_avg", avgGrossSpread, true);
RED.util.setMessageProperty(msg, "dynamic.data_all.net_spread_avg", avgNetSpread, true);

// 6b.
node.status({
    fill: "blue", shape: "dot",
    text: `${strategy} | ${fullPairCount} cycle${fullPairCount === 1 ? '' : 's'} | net Σ${avgNetSpread}¢`
});
log(this, `Strategy: **${strategy}** | cycles=${fullPairCount} low=${lowMarkCount} high=${highMarkCount} unmarked=${n - markedCount} | gross=${grossSpread}¢ net=${avgNetSpread}¢ minDelta=${minDeltaCents}¢ caps=L${cheapestHrs}h/H${expensiveHrs}h`);

return msg;

