if(handle) handle(this);

// Check origin of msg execution
if (msg._linkSource) {
    return msg; // Origin: some other flow
} else {
    return null; // Origin: this flow. Stop to prevent 'Missing return' warning
}

/* Mode selection 
 * 
 * Peak shaving can be triggered by:
 * - Grid power exceeds the import/export limit set by the user
 * 
 * Peak shaving will persist while:
 * - Grid power exceeds the import/export limit set by the user
 * - Batteries are applied to keep system below the limit set by the user
 * 
 * The first is checked in this node.
 * The latter is checked in the last function node of the Peak Shaving flow.
 * Both set the last_power_limit_violation flow variable to Date.now() to persist peak shaving.
 * 
 * PEAK_SHAVING_TIMEOUT_SEC is advised to be kept above atleast 3-5 seconds, to account for rate limiters and other power saving options.
*/

// Timestamp
const now = Date.now();

// Logger
const log = global.get("logger");

// Configuration & State recovery
const PEAK_SHAVING_TIMEOUT_SEC = 10;
let isPeakShaving = flow.get("is_peak_shaving") ?? false;
let lastPowerLimitViolation = flow.get("last_power_limit_violation") ?? now;
let isPowerLimitViolation = false;
let peakDirection = flow.get("peak_shave_direction") || null;
let powerLimit = Number(flow.get("peak_shave_power_limit")) || 0;

// Input data | grid
const P1_power = parseInt(RED.util.getMessageProperty(msg, "grid_power") || 0);
// Input data | Charge PV
const hasImportLimit = RED.util.getMessageProperty(msg, "grid_power_has_limit_import") || false;
const importLimit = parseInt(RED.util.getMessageProperty(msg, "grid_power_limit_import") || 0);
// Input data | Sell PV
const hasExportLimit = RED.util.getMessageProperty(msg, "grid_power_has_limit_export") || false;
const exportLimit = parseInt(RED.util.getMessageProperty(msg, "grid_power_limit_export") || 0);

// ACTIVATE shaving
// Latch the direction and limit at the moment of the real violation. During the
// release timeout the battery response can flip P1 import/export, but that
// should not turn an import shave into an export shave or vice versa.
if (hasImportLimit && (P1_power > importLimit)) {
    isPeakShaving = true;
    isPowerLimitViolation = true;
    peakDirection = "import";
    powerLimit = importLimit;
}
if (hasExportLimit && (P1_power < exportLimit)) {
    isPeakShaving = true;
    isPowerLimitViolation = true;
    peakDirection = "export";
    powerLimit = exportLimit;
}

// UPDATE timer or continue
if (isPowerLimitViolation) lastPowerLimitViolation = now;

// CALCULATE release logic
// Seconds since the last time the power limit was exceeded
let secondsSinceLastViolation = Math.floor((now - lastPowerLimitViolation) / 1000);

// RELEASE shaving logic
// Only release if we are currently shaving AND the timeout has passed
if (isPeakShaving && (secondsSinceLastViolation >= PEAK_SHAVING_TIMEOUT_SEC)) {
    isPeakShaving = false;
    peakDirection = null;
    powerLimit = 0;
    log(this,"Peak Shaving released, resume normal operation");
}

// UI & OUTPUT Logic
if (isPeakShaving) {
    // Timeout progress
    const secondsRemaining = PEAK_SHAVING_TIMEOUT_SEC - secondsSinceLastViolation;
    // Set latched grid power limit
    msg.payload = powerLimit;
    // UI
    node.status({
        fill: "yellow",
        shape: "dot",
        text: isPowerLimitViolation ? "Peak Shaving" : "Peak Shaving: release in " + secondsRemaining + "s"
    });
} else {
    // UI
    node.status({
        fill: "green",
        shape: "dot",
        text: "Grid OK - " + msg.target
    });
}

// Persist state for next run
flow.set("is_peak_shaving", isPeakShaving); 
flow.set("peak_shave_direction", peakDirection);
flow.set("peak_shave_power_limit", powerLimit);
if (isPowerLimitViolation) flow.set("last_power_limit_violation", now); // Power limit exceeded. Update the lastPowerLimitViolation timestamp to current time

// Finalize msg
RED.util.setMessageProperty(msg, "strategy.is_peak_shaving", isPeakShaving, true);
RED.util.setMessageProperty(msg, "strategy.peak_direction", peakDirection, true);

// OUTPUT
return msg;

// Logger
const log = global.get("logger");

// Explain
log(this,`**Peak shaving mode** postponing '${msg.target}' strategy`);
node.status({ fill: "green", shape: "dot", text: `postponing '${msg.target}' strategy`});

// Original target
const ORIGINAL_TARGET = msg.target;

// Use the PID controller strategy
msg.target = "Self-consumption";
// Set the grid power limit
msg.house_target_grid_consumption_in_w = msg.payload;

// Type of peak shave
const peakDirection = RED.util.getMessageProperty(msg, "strategy.peak_direction");
const DISABLED = true;

switch (peakDirection) {
    case "import":
        // Ask PID to help shave import peak
        RED.util.setMessageProperty(msg, "advanced_settings.charge_disabled", DISABLED, true);    
        break;
    case "export":
        // Ask PID to help shave export peak
        RED.util.setMessageProperty(msg, "advanced_settings.discharge_disabled", DISABLED, true);
        break;
    default:
        log(this, `Unknow peak type ${peakDirection}, peak shave failed`, "warn");       
        node.status({ fill: "red", shape: "dot", text: `peak type ${peakDirection}, peak shave failed`});
        // Set a safe value
        msg.house_target_grid_consumption_in_w = 0;
}

return msg;

// Logger
const log = global.get("logger");

// INPUT
const PID_assigned = msg.pid?.load_assigned ?? 0; // calculated battery power delivery, see footnote_1 why this is 0 by default
const isCharging = msg.batteries_charging || false;

// HOLD peak shave when:
if(PID_assigned > 0 && !isCharging) {
    // The batteries are still required to reduce the power peak
    log(this,`**Peak shaving continues**, batteries still required for peak reduction`);
    // Reset timeout timer
    flow.set("last_power_limit_violation", Date.now()); 
    // UI
    node.status({fill:"yellow",shape:"dot",text:`Holding peak shave, batteries still required for ${PID_assigned} W`});
} else {
    // No solution or batteries not required - let timer run out
    node.status({fill:"green",shape:"dot",text:`Relax`});
}

return msg;

// FOOTNOTE_1: 
// Self-consumption won't return `msg.solutions` nor `msg.pid.load_assigned` when:
// - P1 is near or at it's target grid consumption (aka inside deadband)
// - when a non-blocking error occurs
// 
// This code does not specifically account for these cases, but applies a TIMEOUT mechanism instead.
// As PID_assigned is kept 0, the timer won't be updated and runs out.

// explain
const log = global.get("logger");
log(this,"Using self-consumption with charging disabled (Zero import)")

// use the self consumption strategy with charging disabled (Zero import)
msg.target = "Self-consumption";

// tell that strategy to disallow charging
const CHARGE_DISABLED = true;
RED.util.setMessageProperty(msg,"advanced_settings.charge_disabled",CHARGE_DISABLED,true);


return msg;

// explain
const log = global.get("logger");
log(this,"Using self-consumption to standby for peak shaving")

// Show the user-facing strategy name while the internal executor is Self-consumption.
RED.util.setMessageProperty(msg,"strategy.display","Standby / peak shave",true);

// use the self consumption strategy
msg.target = "Self-consumption";

// clamp a zero solution, allowing soft stop of batteries (no click clack)
RED.util.setMessageProperty(msg,"advanced_settings.charge_disabled",true,true);
RED.util.setMessageProperty(msg,"advanced_settings.discharge_disabled",true,true);

return msg;

// On change of Ki setting
let logdata = "bumpless ";
let I_sum = flow.get("I_integral_sum");
let Ki = msg.payload || 0;     // Integral gain
let Ki_last = context.get("house_battery_control_ki_last")||0;

// if Ki was or has become zero
if(Ki == 0 || Ki_last == 0){
    // passify the integral-sum
    flow.set("I_integral_sum",0);
    context.set("house_battery_control_ki_last", Ki);
    logdata += `to/from 0, Ki=${Ki_last} -> ${Ki} | `;
    // done
    return { payload: logdata };
}

// change in Ki
let dKi = parseFloat(Ki/Ki_last);
if(dKi <= 0) dKi = 1; // ignore erroneous changes

// keep I-term constant by compensating the integral-sum for the change in Ki
// e.g. if Ki got 10% smaller, then integral-sum should increase 10%, to keep the I-term constant
let I_sum_new = I_sum / dKi;
logdata += `change of I: from ${Ki_last} to ${Ki} (${dKi * 100}%) | `;

// OUTFLOW
flow.set("I_integral_sum", I_sum_new);
context.set("house_battery_control_ki_last", Ki);

// OUTPUT
return { payload: logdata };

