// Every node-to-node hop puts the message back in Node-RED's queue; on a busy Node-RED those
// waits add up past the Start flow's 1 s link-call timeout. The original node bodies are kept
// VERBATIM below as inner functions and called in the original order, so the maths, the
// context they keep and the log lines are unchanged.
//
// 'Target grid consumption unchanged' compared flow.house_target_grid_consumption_in_w, which
// nothing in this flow ever sets: undefined == undefined, so it ALWAYS took the 'Derivative
// Error' branch. That behaviour is kept as is (Derivative PV is not called).
//
// Outputs:  1 PID output (-> Load distribution, PID Output helper)   2 error signal
//           3 P-term  4 I-term  5 D-term  6 is charging  7 logdata
//           8 halted by deadband (-> go to End)   9 settings cache stale (-> Read PID settings)
const out = [null, null, null, null, null, null, null, null, null];

// --- PID settings cache (was 'PID settings (cached)') -----------------------------------
const MAX_AGE_MS = 10 * 60 * 1000;
if (msg._pid_cfg_fresh) {
    delete msg._pid_cfg_fresh;            // just came back from an in-path read: go on, even if it failed
} else {
    const stamp = Number(flow.get('pid_settings_stamp')) || 0;
    const age = stamp ? Date.now() - stamp : Infinity;
    if (age > MAX_AGE_MS) {
        msg._pid_cfg_inpath = true;
        node.status({ fill: 'yellow', shape: 'ring', text: `settings cache ${Number.isFinite(age) ? Math.round(age / 1000) + ' s old' : 'empty'} - reading HA` });
        out[8] = msg;
        return out;
    }
}

// --- original node bodies, verbatim ----------------------------------------------------
function advancedSettings(msg) {
// 1. Hard coded advanced settings (flow level)
flow.set("has_soc_charging_limiter", true);         // slows charging from 95% to 100% to improve battery life
flow.set("master_gain", 1);                         // Gain scheduling. Not Implemented!

// 2. Configurable advanced settings (msg level)
msg.advanced_settings ||= {}; // creates 'advanced_settings' if it does net yet exist
let mas = msg.advanced_settings;

// The nullish coalescing (??) operator is a logical operator that returns its right-hand side operand when its left-hand side operand is null or undefined
// Disable charge or discharge solutions and changes them to stop solutions
RED.util.setMessageProperty(msg,"advanced_settings.discharge_disabled", mas.discharge_disabled ?? false);
RED.util.setMessageProperty(msg,"advanced_settings.charge_disabled", mas.charge_disabled ?? false);
// Prioritize discharging and charging the same battery when batteries are charged one by one
RED.util.setMessageProperty(msg, "advanced_settings.reverse_discharge_priority",mas.reverse_discharge_priority ?? true);

// 3. continue
return msg;

// Notes for home battery tinkerer friends:
// Using RED.util.getMessageProperty / RED.util.setMessageProperty is more performant and safe.
// If any part of the path ("foo.bar") is missing, it will return 'undefined' without throwing an error.
}
function setErrorSignal(msg) {
// INPUTS
let P1_error_last = Number(context.get("p1_error_last"))||0; // last error signal level in W
let dampening = Number(flow.get("house_battery_control_error_signal_dampening")) || 0; // 0% - 100%
dampening = dampening / 100; // to Number

// Process Variable (PV) currently measured grid power, Setpoint (SP) desired grid power, set 0 for NoM
var P1_power = msg.grid_power; // PV: consume is positive, supply to grid is negative
var P1_setpoint = Number(RED.util.getMessageProperty(msg,"house_target_grid_consumption_in_w")); // SP: target value

// Calc error signal
let P1_error_unfiltered = P1_setpoint - P1_power;

// Simple averaging filter
let P1_error_filtered = (1 - dampening) * P1_error_unfiltered + (dampening) * P1_error_last;

// OUTFLOW
context.set("p1_error_last", P1_error_filtered);

// OUTPUT
msg.grid_error = P1_error_filtered; // W (watt), error signal = SP - PV
return msg;
}
function deadband(msg) {
// Deadband
// Stop processing if error is within .. Watt of target grid consumption.
// This to reduce CPU loads 

// Logger
const log = global.get("logger");

// P1
let P1_error = msg.grid_error; // Watt
let P1_deadband = 15; // Watt

// TODO
// based on last 'assignable power' and current error, if (error > assignable power) the system will never enter the deadband. And keep calculating each interation.
// however since we don't know if the is the assignable power will change, until we calculate the Control Value / load balancer
// we could end up in a deadlock if we simply stop execution here, based on assignable power alone.

// Within Deadband
if(Math.abs(P1_error) < P1_deadband) {
    // stop processing
    node.status({fill:"yellow",shape:"dot",text:`Halt, ${Math.round(Math.abs(P1_error))} W`});
    log(this, `**Stopped processing** 🌿power saving, ${Math.round(Math.abs(P1_error))} W is within deadband of ${P1_deadband} W`);
    msg.payload = 'halted by deadband';
    return msg;
} 

// Outside deadband
node.status({fill:"green",shape:"dot",text:`Pass, ${Math.round(Math.abs(P1_error))} W`});
return msg;

}
function derivativeError(msg) {
var P1_error = msg.grid_error||0;
var P1_last_error = Number(context.get("p1_last_error")) ||0;

// Error derivative
// note: error = -PV
// note: for simplicity we assume 1 second time steps
let p1_derivative = -(P1_error - P1_last_error); // devided by unity seconds

// OUTFLOW
context.set("p1_last_error", P1_error);

// OUTPUT
msg.grid_derivative = p1_derivative;
return msg;
}
function calculateCorrections(msg) {
// Logger
var logdata = ""; // deprecated
const log = global.get("logger");

// Timing
let time_last = context.get('time_last') || Date.now(); // Milliseconds
let time_current = Date.now(); // Milliseconds
let time_delta = (time_current - time_last) / 1000; // Convert to seconds
// note: due to inherent 1 sec intervals of P1 meter we omit dt terms. This is mostly for bug checking and optimizations.

// Batteries
var B_power = msg.batteries_total_power; // charging is positive, discharging negative
var anti_windup_threshold = Number(flow.get("batteries_total_assignable_power")) || 0; // max available charge/discharge power.

// Process Variable (PV) currently measured grid power, Setpoint (SP) desired grid power, set 0 for NoM
var P1_power = msg.grid_power; // PV: consume is positive, supply to grid is negative
var P1_setpoint = flow.get("house_target_grid_consumption_in_w"); // SP: target value
var P1_error = msg.grid_error;  // W (watt), error signal = SP - PV
var P1_derivative = msg.grid_derivative; // Derivative of PV, not the error

// PID values
var Kp = flow.get("house_battery_control_kp") || 0.75;  // Proportional gain
var Ki = flow.get("house_battery_control_ki") || 0;     // Integral gain        Ki = Kp/Ti
var Kd = flow.get("house_battery_control_kd") || 0;     // Derivative gain      Kd = Kp*Td

// helpers
var I_integral_sum = flow.get('I_integral_sum') || 0;
var Gm = flow.get("master_gain")||1; // gain scheduling

// optimizations
var hysteresis = flow.get("house_battery_control_hysteresis_in_w"); // W (watt)

// advanced settings
const isDischargeDisabled = RED.util.getMessageProperty(msg,"advanced_settings.discharge_disabled");
const isChargeDisabled = RED.util.getMessageProperty(msg,"advanced_settings.charge_disabled");

// -- PID regulator --
// Proportional term
let p_term = Gm * Kp * P1_error;

// Integral term
let integral_max = 0;
if (Ki > 0) {
    // Integral term | integrate
    I_integral_sum += P1_error; 
    // Integral term | apply anti-windup
    integral_max = anti_windup_threshold / Ki; // the anti-windup value is set to the current controlable range of the batteries, given by the previous load balancer calculations
    I_integral_sum = Math.min(Math.max(I_integral_sum, -integral_max), integral_max);
} else {
    // If Ki is 0, keep everything 0
    I_integral_sum = 0;
    integral_max = 0;
}

// Integral term | the term
let i_term = Ki * I_integral_sum;

// Integral term | explain
logdata += `anti_windup_threshold=${anti_windup_threshold}, integral_max=${integral_max}| `; // deprecated

// Differential term
let d_term = Gm * Kd * (-P1_derivative); // omitted '/time_delta'. inherent P1 refresh fequency.

// Total PID output
var PID_output = p_term + i_term + d_term; // W (watt), the control input for the battery packs

// Feed-forward start (2026-10-15), sent by the Charge flow's 'Regulated power' node while it
// holds its start power. Output that power directly and seed the integral with it, so the PID
// carries on from there (instead of building up from 0) once the hold ends.
const ff_power = Number(msg.pid_feedforward_w);
if (Number.isFinite(ff_power) && ff_power > 0 && Ki > 0 && !isChargeDisabled) {
    PID_output = ff_power;
    p_term = 0;
    d_term = 0;
    I_integral_sum = Math.min(ff_power / Ki, integral_max > 0 ? integral_max : ff_power / Ki);
    i_term = Ki * I_integral_sum;
    log(this, `**Feed-forward** holding ${Math.round(ff_power)} W, integral seeded`);
}

// Charging or Discharging states
var B_was_charging = context.get("batteries_charging_last") || false;
var B_is_charging = PID_output > 0 ? true : false;

// Explain
logdata += `U(${time_delta}s)[${PID_output}] = P(${Kp})[${p_term}] + I(${Ki})[${i_term}] + D(${Kd})[${d_term}] | `; // deprecated
log(this,`**PID Controller**`);
log(this,`Step size: ${time_delta} s`);
if(Kp == 0 && Ki == 0 && Kd == 0) {
    log(this, `<font color="orange">**Controller disabled**</font> All PID gains are 0. Choose a PID preset or set gains > 0.`,"warn");
} else {
    // log(this, `P-term: ${Math.floor(p_term)} W @ P-gain ${Kp}`);
    // log(this, `I-term: ${Math.floor(i_term)} W @ I-gain ${Ki} (max. ${anti_windup_threshold} W)`);
    // log(this, `D-term: ${Math.floor(d_term)} W @ D-gain ${Kd}`);
    log(this, `**P** ${Math.floor(p_term)} W @ gain ${Kp}<br>**I** ${Math.floor(i_term)} W @ gain ${Ki} (max. ${anti_windup_threshold} W)<br>**D** ${Math.floor(d_term)} W @ gain ${Kd}`);
    log(this, `**PID ${B_is_charging ? 'Charge' : 'Discharge'}:** ${Math.floor(p_term)} + ${Math.floor(i_term)} + ${Math.floor(d_term)} = **${Math.round(PID_output)} Watt**`);
}

// Only one of the advanced settings below can be active at once.
// Advanced setting | discharge disabled
if(isDischargeDisabled && !B_is_charging) {
    // log explain
    logdata += `Discharging disabled, PID unwound U(${time_delta})[0]=0+0+0 | `;
    log(this,'**PID capped at 0**. Discharge is disabled in this strategy'); // via `msg.advanced_settings`
    // Set all PID terms to 0 and unwind integral sum
    PID_output = 0;
    p_term = 0;
    i_term = 0;
    d_term = 0;
    I_integral_sum = 0; // unwind
    // maintain charge scenario
    B_is_charging = true;

// Advanced setting | charge disabled
} else if (isChargeDisabled && B_is_charging) {
    // log explain
    logdata += `Charging disabled, PID unwound U(${time_delta})[0]=0+0+0 | `;
    log(this,'**PID capped at 0**. Charge is disabled in this strategy'); // via `msg.advanced_settings`
    // Set all PID terms to 0 and unwind integral sum
    PID_output = 0;
    p_term = 0;
    i_term = 0;
    d_term = 0;
    I_integral_sum = 0; // unwind
    // maintain discharge scenario
    B_is_charging = false;

// Advanced setting | hysteresis
} else if 
// prevents excessive switching between (dis)charge mode around the zero point.
// if new PID_output lies within hysteresis, it will not switch charge mode. 
// set hysteresis to 0, to apply no hysteresis
(B_is_charging !== B_was_charging && Math.abs(PID_output) < hysteresis){
    // log explain
    logdata += `Hysteresis prevented charge mode switch from ${B_was_charging ? "charging" : "discharging"} to ${B_is_charging ? "charging" : "discharging"} as ${Math.abs(PID_output)}W <= ${hysteresis}(hyst) | `;
    log(this,`Hysteresis prevented charge mode switch from ${B_was_charging ? "charging" : "discharging"} to ${B_is_charging ? "charging" : "discharging"} as ${Math.abs(PID_output)}W <= ${hysteresis}(hyst)`);
    // prevent negative charging or positive discharging values (not allowed)
    PID_output = (PID_output < 0 && B_is_charging) || ((PID_output > 0 && !B_is_charging)) ? 0 : PID_output;
    // maintain previous scenario
    B_is_charging = B_was_charging;
} 

// save for next iteration
context.set("batteries_charging_last", B_is_charging); //boolean

// OUTFLOW
context.set("time_last", Date.now());
flow.set("I_integral_sum", I_integral_sum);

// OUTPUT
RED.util.setMessageProperty(msg, "batteries_charging", B_is_charging, true);
RED.util.setMessageProperty(msg, "I_integral_sum", I_integral_sum,true);
msg.payload = Number(PID_output);

return [msg, // payload = PID_output
        { payload: Math.round(Number(P1_error))},
        { payload: Math.round(parseFloat(p_term))},
        { payload: Math.round(parseFloat(i_term))},
        { payload: Math.round(parseFloat(d_term))},
        { payload: B_is_charging},
        { payload: logdata }];
}
function outputDampening(msg) {
// INPUT
let PID_unfiltered = msg.payload; // W Watt
let PID_last = context.get("PID_last")||0; // W watt
let PID_damp = Number(flow.get("house_battery_control_pid_output_dampening"))||0; // 0% - 100%
PID_damp = PID_damp/100; // to Number

// simple averaging filter
let PID_filtered = (1-PID_damp)*PID_unfiltered + (PID_damp)*PID_last;

// OUTFLOW
context.set("PID_last", PID_filtered);

// OUTPUT
msg.payload = Number(PID_filtered)
return msg;
}
function outputFailsafe(msg) {
// INFLOW
let maxCharge = msg.batteries_max_charge_power||undefined;
let maxDischarge = msg.batteries_max_discharge_power||undefined;
let isCharging = msg.batteries_charging||undefined;
let PID_output = msg.payload; // Watt

// No failsafe
if (maxCharge === undefined || maxDischarge == undefined) {
    node.status({ fill: "red", shape: "dot", text: "disabled" });
    node.warn(`Output Failsafe is INACTIVE. Max charge or discharge limits are undefined`);
    // continue without safeguard
    return msg;
} 

// limit
let limit = 0;

// charging state unknown
if(isCharging === undefined) {
    // limit on lowest of charge / discharge
    limit = Math.min(maxCharge,maxDischarge);    
}
// charging state known
limit = isCharging ? maxCharge : maxDischarge;

// Safe output
if (PID_output <= limit){
    node.status({ fill: "green", shape: "dot", text: "safe" });
    msg.payload = Math.round(msg.payload);
    return msg;
} 

// Unsafe, limit output
node.status({ fill: "yellow", shape: "ring", text: "power limiting" });
msg.payload = Math.round(Number(limit));
return msg;
}

// --- the chain ---------------------------------------------------------------------------
msg = advancedSettings.call(this, msg);
msg = setErrorSignal.call(this, msg);
msg = deadband.call(this, msg);
if (msg.payload === 'halted by deadband') {      // was: switch 'Pass or Halt'
    out[7] = msg;
    return out;
}
msg = derivativeError.call(this, msg);           // was: switch 'Target grid consumption unchanged' (see top)
const c = calculateCorrections.call(this, msg);  // [msg, error, P, I, D, charging, logdata]
// Feed-forward bypasses output dampening (and primes it), otherwise the jump is smoothed away
let m;
if (Number.isFinite(Number(c[0].pid_feedforward_w)) && Number(c[0].pid_feedforward_w) > 0 && c[0].batteries_charging) {
    context.set("PID_last", c[0].payload);
    m = c[0];
} else {
    m = outputDampening.call(this, c[0]);
}
m = outputFailsafe.call(this, m);
out[0] = m;
for (let i = 1; i < 7; i++) out[i] = c[i];
return out;

// Logger, usage: log(this, "");
const log = global.get('logger');
log(this, "Discharge at **max. power**");

// INPUT
let batteries = msg.batteries;
let solution_array = [];

// build solution
msg.batteries.forEach(battery => {
    const calculatedPower = Number(battery.discharging_max);

    solution_array.push({
        id: battery.id,
        mode: "discharge",
        power: calculatedPower
    });

});

// return solution
msg.solutions = solution_array;
return msg;

// Logger, usage: log(this, "");
const log = global.get('logger');

// Which sub-strategy to use
msg.target = "Self-consumption";

// Grid power limit
const targetGridPower = parseInt(msg.grid_power_limit_export);

// Set target grid consumption for the PID controller
msg.house_target_grid_consumption_in_w = -targetGridPower; // negative, we are exporting to grid.
// tell PID to avoid charge solutions during Selling.
RED.util.setMessageProperty(msg,"advanced_settings.charge_disabled",true,true);

// Finally
log(this, `**Regulated** discharging. Target grid power: ${Math.floor(targetGridPower)} W`);
return msg;

// Lower bound
let output = msg.sell.threshold_energy || 0; // kWh
output = Math.max(output, 0);

// Upper bound
let max_reserve = 0; // kWh
msg.batteries.forEach(battery => {
    max_reserve += (Number(battery.energy_max*battery.soc_max) - Number(battery.energy_max*battery.soc_min))/100; // kWh
});
output = Math.min(output, max_reserve);

node.status({fill:"blue",shape:"dot",text:`${output}`});

// Output
msg.payload = output;

return msg;

const log = global.get("logger");

// Unkown export goal
log(this, `**${msg.sell.goal}**; Sell goal not recognized. Fallback to **Full Stop**`,"warn");

// Full stop
msg.target = "Full stop";

return msg;

// 1. Get the custom logger from global context
const log = global.get("logger");
log(this,`Sell until: ${msg.sell.goal}`);

// 2. Extract energy level from msg (default to 0 if property is missing)
const energy_remaining = Number(RED.util.getMessageProperty(msg, "batteries_available_energy")) || 0;
var energy_threshold = Number(RED.util.getMessageProperty(msg,"sell.threshold_energy"));
if (energy_threshold === undefined || energy_threshold < 0){
    log(this,`Desired energy reserve not set correctly '${energy_threshold}' kWh`,"warn");
    energy_threshold = 0;
}

// 3. Logic: Determine if energy level is at or below zero
if (energy_remaining <= energy_threshold) {
    msg.sell.threshold_reached = true;

    // User friendly feedback via the custom logger
    log(this, `[STOP] Energy reserve at ${energy_remaining.toFixed(1)} / ${energy_threshold.toFixed(1)} kWh`, 'info');
} else {
    msg.sell.threshold_reached = false;

    // User friendly feedback via the custom logger
    log(this, `[OK] Energy reserve at ${energy_remaining.toFixed(1)} / ${energy_threshold.toFixed(1)} kWh.`, 'info');
}

// 4. Update node status for visual feedback in the editor
node.status({ 
    fill: msg.sell.threshold_reached ? "red" : "green", 
    shape: "dot", 
    text: `Threshold reached: ${msg.sell.threshold_reached}` 
});

return msg;

// 1. Get the custom logger from global context
const log = global.get("logger");
log(this, `Sell until: ${msg.sell.goal}`);

// 2. Extract average SoC and desired SoC level
let batteries = msg.batteries;
let soc_avg = 0;
let count = 0; // could use msg.battery_count
batteries.forEach(battery => {
    soc_avg += battery.soc;
    count++;
});
// 2a.  Current avg. SoC
soc_avg = Math.round(soc_avg / count * 100) / 100;
// 2b.  Sell until SoC (11% as fallback)
var soc_threshold = Number(RED.util.getMessageProperty(msg,"sell.threshold_soc"));
if (soc_threshold === undefined || soc_threshold < 11){
    log(this, `Desired SoC not set correctly '${soc_threshold}' %. I've set it to 11%.`,"warn");
    soc_threshold = 11;
}

// 3. Logic: Determine if SoC level is at or below desired level
if (soc_avg <= msg.payload) {
    msg.sell.threshold_reached = true;

    // User friendly feedback via the custom logger
    log(this, `[STOP] Average SoC at ${soc_avg.toFixed(1)}/${soc_threshold.toFixed(1)} %.`, 'info');
} else {
    msg.sell.threshold_reached = false;

    // User friendly feedback via the custom logger
    log(this, `[OK] Average SoC at ${soc_avg.toFixed(1)}/${soc_threshold.toFixed(1)} %.`, 'info');
}

// 4. Update node status for visual feedback in the editor
node.status({
    fill: msg.sell.threshold_reached ? "red" : "green",
    shape: "dot",
    text: `Threshold reached: ${msg.sell.threshold_reached}`
});

return msg;

// 1. Get the custom logger from global context
const log = global.get("logger");
log(this,`Sell until: ${msg.sell.goal}`);

// 2. Extract energy level from msg (default to 0 if property is missing)
const energy_remaining = Number(RED.util.getMessageProperty(msg, "batteries_available_energy")) || 0;

// 3. Logic: Determine if energy level is at or below zero
if (energy_remaining <= 0) {
    msg.sell.threshold_reached = true;

    // User friendly feedback via the custom logger
    log(this, `[STOP] All batteries are empty or at SoC_min_ (${energy_remaining} kWh).`, 'info');
} else {
    msg.sell.threshold_reached = false;

    // User friendly feedback via the custom logger
    log(this, `[OK] Battery level ${energy_remaining.toFixed(2)} kWh above 0 kWh.`, 'info');
}

// 4. Update node status for visual feedback in the editor
node.status({ 
    fill: msg.sell.threshold_reached ? "red" : "green", 
    shape: "dot", 
    text: `Threshold reached: ${msg.sell.threshold_reached}` 
});

return msg;

// Which strategy to run after the goal is reached
const goal = msg.charge.goal_reached_strategy || "Charge PV";
msg.target = goal;
return msg;

const log = global.get("logger");

if(msg.sell.threshold_reached){
    log(this,`Stop discharging, Sell until ${msg.sell.goal} reached.`);
} else {
    log(this,`Continue discharging.`);
}

return msg;

// Log unhandled exception
const handle = global.get('unhandledException');
if(handle) handle(this);

// Check origin of msg execution
if (msg._linkSource) {
    return msg; // Origin: some other flow
} else {
    return null; // Origin: this flow. Stop to prevent 'Missing return' warning
}

// Pick period (2026-10-16) - replaces, on the hot path, the chain of 20 api-current-state
// reads, 5 config functions, 5 time-range switches and ~15 change/switch nodes that ran in
// series on every P1 update. Same decision, same order:
//   * period A is always checked; B is checked only if 'has period B' is on, C only if B AND
//     C are on, and so on - the old chain stopped at the first period that was switched off;
//   * the first period whose window contains 'now' wins; none -> the baseline strategy;
//   * a window is [start, end) to the second; end before start runs past midnight; start ==
//     end is an empty period (exactly how node-red-contrib-time-range-switch 1.2.0 decides).
// 'now' is Home Assistant's local time (UTC + HA's offset from the settings snapshot), so
// this flow and the HA sensors that describe the Timed periods agree on the clock even when
// the Node-RED container runs in another timezone.
//
// Outputs: 1 -> Sub strategy (the hot path, no fan-out so the msg is not cloned)
//          2 -> Update UI, ONLY when the period changes, after a pause (Timed was not the
//               active strategy and the UI may say 'not timed'), or every 10 min as a repair
//          3 -> the old read chain, used only when there is no fresh settings snapshot
const log = global.get('logger');
const cfg = flow.get('timed_cfg');
const MAX_AGE_MS = 5 * 60 * 1000;
const nowMs = Date.now();
const age = (cfg && Number(cfg.stamp)) ? nowMs - Number(cfg.stamp) : Infinity;

if (!cfg || age > MAX_AGE_MS) {
    const lastWarn = Number(context.get('stale_warned')) || 0;
    if (nowMs - lastWarn > 60000) {
        context.set('stale_warned', nowMs);
        node.warn(`[Timed] settings snapshot ${Number.isFinite(age) ? Math.round(age / 1000) + ' s old' : 'missing'} - using the old read chain`);
    }
    node.status({ fill: 'yellow', shape: 'ring', text: 'no fresh settings - old read chain' });
    context.set('last_run', nowMs);
    return [null, null, msg];
}

const toSec = v => {
    const m = /^(\d{1,2}):(\d{2})(?::(\d{2}))?/.exec(String(v));
    return m ? Number(m[1]) * 3600 + Number(m[2]) * 60 + Number(m[3] || 0) : null;
};
const nowS = (((Math.floor(nowMs / 1000) + Number(cfg.utc_offset_s)) % 86400) + 86400) % 86400;
const inRange = (s, e) => s < e ? (nowS >= s && nowS < e)
                        : s > e ? (nowS >= s || nowS < e)
                        : false;

let period = 'Default';
let strat = cfg.strat_0;
for (const p of cfg.periods) {
    if (!p.enabled) break;                         // same cascade as the old chain
    const s = toSec(p.start), e = toSec(p.end);
    if (s === null || e === null) {
        // The old time-range switch errored out on an unreadable time; skip the period instead.
        const lastBad = Number(context.get('bad_warned')) || 0;
        if (nowMs - lastBad > 60000) {
            context.set('bad_warned', nowMs);
            node.warn(`[Timed] period ${p.id} has an unreadable time (${p.start} - ${p.end}) - skipped`);
        }
        continue;
    }
    if (inRange(s, e)) { period = p.id; strat = p.strat; break; }
}

// Same message properties the old chain left behind.
msg.timed_strategy = strat;
msg.target = strat;
msg.timed_period = period;

// UI write, throttled.
const lastRun = Number(context.get('last_run')) || 0;
const lastUi = Number(context.get('ui_time')) || 0;
const resumed = nowMs - lastRun > 10000;           // Timed was not running for a while
const uiDue = context.get('ui_period') !== period || resumed || (nowMs - lastUi) > 10 * 60 * 1000;
context.set('last_run', nowMs);
let ui = null;
if (uiDue) {
    context.set('ui_period', period);
    context.set('ui_time', nowMs);
    ui = { timed_period: period };
}

const hh = String(Math.floor(nowS / 3600)).padStart(2, '0'), mm = String(Math.floor(nowS / 60) % 60).padStart(2, '0');
node.status({ fill: 'green', shape: 'dot', text: `${hh}:${mm} ${period} -> ${strat}` });
return [msg, ui, null];

// Publish the Timed settings snapshot to flow context (2026-10-16).
// 'Pick period' runs on every P1 update (~1 Hz) and reads ONLY this snapshot. The 20
// api-current-state reads it replaces fetched values that change only when someone edits a
// period on the dashboard. Refreshed on every change of one of those helpers, and every 30 s
// as a repair (that also picks up a daylight-saving change in utc_offset_s).
// A bad render keeps the PREVIOUS snapshot; Pick period falls back to the old read chain on
// its own once the snapshot is more than 5 minutes old.
const cfg = msg.timed_cfg;
const ok = cfg && typeof cfg === 'object' && Array.isArray(cfg.periods) && cfg.periods.length === 5
    && Number.isFinite(Number(cfg.utc_offset_s));
if (!ok) {
    node.status({ fill: 'red', shape: 'ring', text: `settings render failed ${new Date().toLocaleTimeString()}` });
    node.warn('[Timed] settings template returned nothing usable - keeping the previous snapshot');
    return null;
}
cfg.stamp = Date.now();
flow.set('timed_cfg', cfg);
const on = cfg.periods.filter(x => x.enabled).map(x => x.id).join('');
node.status({ fill: 'grey', shape: 'dot', text: `periods ${on || '-'} @ ${new Date().toLocaleTimeString()}` });
return null;                         // a settings refresh never continues into the flow

msg.__config = {
    startTime: RED.util.getMessageProperty(msg,'house_battery_strategy_timed_period_a1'),
    endTime: RED.util.getMessageProperty(msg,'house_battery_strategy_timed_period_a2'),
    startOffset: 0,
    endOffset: 0
}

return msg;

msg.__config = {
    startTime: RED.util.getMessageProperty(msg,'house_battery_strategy_timed_period_b1'),
    endTime: RED.util.getMessageProperty(msg,'house_battery_strategy_timed_period_b2'),
    startOffset: 0,
    endOffset: 0
}

return msg;

msg.__config = {
    startTime: RED.util.getMessageProperty(msg,'house_battery_strategy_timed_period_c1'),
    endTime: RED.util.getMessageProperty(msg,'house_battery_strategy_timed_period_c2'),
    startOffset: 0,
    endOffset: 0
}

return msg;

// Log unhandled exception
const handle = global.get('unhandledException');
if(handle) handle(this);

// Check origin of msg execution
if (msg._linkSource) {
    return msg; // Origin: some other flow
} else {
    return null; // Origin: this flow. Stop to prevent 'Missing return' warning
}

msg.__config = {
    startTime: RED.util.getMessageProperty(msg,'house_battery_strategy_timed_period_d1'),
    endTime: RED.util.getMessageProperty(msg,'house_battery_strategy_timed_period_d2'),
    startOffset: 0,
    endOffset: 0
}

return msg;

msg.__config = {
    startTime: RED.util.getMessageProperty(msg,'house_battery_strategy_timed_period_e1'),
    endTime: RED.util.getMessageProperty(msg,'house_battery_strategy_timed_period_e2'),
    startOffset: 0,
    endOffset: 0
}

return msg;
